	{ "Increases your spell damage and healing by up to 33% of your Intellect.", "Increases your spell damage and healing by up to 66% of your Intellect.", "Increases your spell damage and healing by up to 100% of your Intellect." },
	{ "Reduces the cast time of your Hammer of Wrath by 0.5 sec, and reduces all threat you generate by 10% while Righteous Fury is not active.", "Reduces the cast time of your Hammer of Wrath by 1 sec, and reduces all threat you generate by 20% while Righteous Fury is not active." },
	{ "Reduces the Mana cost of your Seal spells by 20%, and when you replace your Seal of Command, Seal of Righteousness, Seal of Fury, or Seal of Justice with a different Seal, gain an Echo of that Seal. Your next melee attack applies the replaced Seal's effects, consuming the Echo." },
},
[361] = {
	{ "While Aspect of the Hawk is active, Auto Shot has a 2% chance of increasing ranged attack speed by 30% for 12 sec. While Aspect of the Beast is active, all melee auto attacks have a 2% chance of increasing melee attack speed by 30% for 12 sec.", "While Aspect of the Hawk is active, Auto Shot has a 4% chance of increasing ranged attack speed by 30% for 12 sec. While Aspect of the Beast is active, all melee auto attacks have a 4% chance of increasing melee attack speed by 30% for 12 sec.", "While Aspect of the Hawk is active, Auto Shot has a 6% chance of increasing ranged attack speed by 30% for 12 sec. While Aspect of the Beast is active, all melee auto attacks have a 6% chance of increasing melee attack speed by 30% for 12 sec.", "While Aspect of the Hawk is active, Auto Shot has a 8% chance of increasing ranged attack speed by 30% for 12 sec. While Aspect of the Beast is active, all melee auto attacks have a 8% chance of increasing melee attack speed by 30% for 12 sec.", "While Aspect of the Hawk is active, Auto Shot has a 10% chance of increasing ranged attack speed by 30% for 12 sec. While Aspect of the Beast is active, all melee auto attacks have a 10% chance of increasing melee attack speed by 30% for 12 sec." },
	{ "Increases the Health and Armor of your pets by 3%.", "Increases the Health and Armor of your pets by 6%.", "Increases the Health and Armor of your pets by 9%.", "Increases the Health and Armor of your pets by 12%.", "Increases the Health and Armor of your pets by 15%." },
	{ "Increases all damage you and your pet deal by 1% while your pet is active.", "Increases all damage you and your pet deal by 2% while your pet is active." },
	{ "Increases the Dodge bonus of your Aspect of the Monkey by 2%. Additionally, your pet gains 50% of the effect of your Aspect of the Monkey ability.", "Increases the Dodge bonus of your Aspect of the Monkey by 4%. Additionally, your pet gains 50% of the effect of your Aspect of the Monkey ability.", "Increases the Dodge bonus of your Aspect of the Monkey by 6%. Additionally, your pet gains 50% of the effect of your Aspect of the Monkey ability." },
	{ "Increases the speed bonus of your Aspect of the Cheetah and Aspect of the Pack by 3%.", "Increases the speed bonus of your Aspect of the Cheetah and Aspect of the Pack by 6%." },
	{ "Revive Pet's casting time is reduced by 3 sec, mana cost is reduced by 20%, and increases the health your pet returns with by an additional 15%.", "Revive Pet's casting time is reduced by 6 sec, mana cost is reduced by 40%, and increases the health your pet returns with by an additional 30%." },
	{ "Increases the movement speed of your pets by 30%." },
	{ "Increases the damage done by your pets and hawks by 3%.", "Increases the damage done by your pets and hawks by 6%.", "Increases the damage done by your pets and hawks by 9%.", "Increases the damage done by your pets and hawks by 12%.", "Increases the damage done by your pets and hawks by 15%." },
	{ "Gives your Mend Pet spell a 15% chance of cleansing 1 Curse, Disease, Magic, or Poison effect from your pet each time it heals and reduces the Mana cost by 10%.", "Gives your Mend Pet spell a 50% chance of cleansing 1 Curse, Disease, Magic, or Poison effect from your pet each time it heals and reduces the Mana cost by 20%." },
	{ "Increases the critical strike chance of your pets and hawks by 2%.", "Increases the critical strike chance of your pets and hawks by 4%.", "Increases the critical strike chance of your pets and hawks by 6%.", "Increases the critical strike chance of your pets and hawks by 8%.", "Increases the critical strike chance of your pets and hawks by 10%." },
	{ "Command a hawk to dive-bomb your targeted enemy, dealing 32 Physical damage and continuing its assault for 18 sec. Only 2 hawks can be active at once. Summon Hawk shares its cooldown with Arcane Shot.", cost = "80 Mana | 35 yd range | Instant | 6 sec cooldown" },
	{ "While your pet is active, you and your pet will regenerate 1% of total health every 10 sec.", "While your pet is active, you and your pet will regenerate 1% of total health every 5 sec." },
	{ "Command your pet to Stun the target for 3 sec on its next successful attack, which also gains 100% increased critical strike chance. Generates high threat.", cost = "8% of base mana | 100 yd range | Instant | 1 min cooldown" },
	{ "Increases the Focus regeneration of your pets by 10% and allows 25% of your Mana regeneration to continue while casting.", "Increases the Focus regeneration of your pets by 20% and allows 50% of your Mana regeneration to continue while casting." },
	{ "Gives your pet a 20% chance to gain a 30% attack speed increase for 8 sec after dealing a critical strike.", "Gives your pet a 40% chance to gain a 30% attack speed increase for 8 sec after dealing a critical strike.", "Gives your pet a 60% chance to gain a 30% attack speed increase for 8 sec after dealing a critical strike.", "Gives your pet a 80% chance to gain a 30% attack speed increase for 8 sec after dealing a critical strike.", "Gives your pet a 100% chance to gain a 30% attack speed increase for 8 sec after dealing a critical strike." },
	{ "Send your pet into a rage causing 50% additional damage for 18 sec. While enraged, the beast does not feel pity or remorse or fear and it cannot be stopped unless killed.", cost = "12% of base mana | 100 yd range | Instant | 2 min cooldown" },
},
[363] = {
	{ "Increases the range of your ranged weapons by 2 yards.", "Increases the range of your ranged weapons by 4 yards.", "Increases the range of your ranged weapons by 6 yards." },
	{ "Gives your Concussive Shot a 4% chance to stun the target for 3 sec.", "Gives your Concussive Shot a 8% chance to stun the target for 3 sec.", "Gives your Concussive Shot a 12% chance to stun the target for 3 sec.", "Gives your Concussive Shot a 16% chance to stun the target for 3 sec.", "Gives your Concussive Shot a 20% chance to stun the target for 3 sec." },
	{ "Increases your critical strike chance with all attacks by 1%.", "Increases your critical strike chance with all attacks by 2%.", "Increases your critical strike chance with all attacks by 3%.", "Increases your critical strike chance with all attacks by 4%.", "Increases your critical strike chance with all attacks by 5%." },
	{ "Increased the damage of your Serpent Sting ability by 6%, reduces the cooldown of your Viper Sting ability by 2 sec, and increases the duration of your Scorpid Sting ability by 15 sec.", "Increased the damage of your Serpent Sting ability by 13%, reduces the cooldown of your Viper Sting ability by 4 sec, and increases the duration of your Scorpid Sting ability by 30 sec.", "Increased the damage of your Serpent Sting ability by 20%, reduces the cooldown of your Viper Sting ability by 6 sec, and increases the duration of your Scorpid Sting ability by 45 sec." },
	{ "Reduces the Mana cost of your Shots, Stings, and melee abilities by 3%.", "Reduces the Mana cost of your Shots, Stings, and melee abilities by 6%.", "Reduces the Mana cost of your Shots, Stings, and melee abilities by 9%.", "Reduces the Mana cost of your Shots, Stings, and melee abilities by 12%.", "Reduces the Mana cost of your Shots, Stings, and melee abilities by 15%." },
	{ "Increases your Attack Power by 20% of your Intellect.", "Increases your Attack Power by 40% of your Intellect.", "Increases your Attack Power by 60% of your Intellect.", "Increases your Attack Power by 80% of your Intellect.", "Increases your Attack Power by 100% of your Intellect." },
	{ "Reduces the cooldown on your Rapid Fire ability by 1 min. In addition, when you kill a non-trivial enemy or it dies while afflicted by your Serpent Sting, you gain Rapid Killing, increasing the damage of your next Shot ability within 20 sec by 10%.", "Reduces the cooldown on your Rapid Fire ability by 2 min. In addition, when you kill a non-trivial enemy or it dies while afflicted by your Serpent Sting, you gain Rapid Killing, increasing the damage of your next Shot ability within 20 sec by 20%." },
	{ "Reduces the cooldown of your Arcane Shot by 0.3 sec. Does not affect the cooldown of abilities which share a cooldown with Arcane Shot.", "Reduces the cooldown of your Arcane Shot by 0.6 sec. Does not affect the cooldown of abilities which share a cooldown with Arcane Shot.", "Reduces the cooldown of your Arcane Shot by 0.9 sec. Does not affect the cooldown of abilities which share a cooldown with Arcane Shot.", "Reduces the cooldown of your Arcane Shot by 1.2 sec. Does not affect the cooldown of abilities which share a cooldown with Arcane Shot.", "Reduces the cooldown of your Arcane Shot by 1.5 sec. Does not affect the cooldown of abilities which share a cooldown with Arcane Shot." },
	{ "You deal 20% increased damage with all attacks while you do not have an active pet." },
	{ "Increases the Ranged Attack Power of party members within 45 yards by 30. Lasts 30 min.", cost = "180 Mana | Instant" },
	{ "Increases the critical strike damage bonus on all ranged abilities by 6%.", "Increases the critical strike damage bonus on all ranged abilities by 12%.", "Increases the critical strike damage bonus on all ranged abilities by 18%.", "Increases the critical strike damage bonus on all ranged abilities by 24%.", "Increases the critical strike damage bonus on all ranged abilities by 30%." },
	{ "Hitting a target with your Serpent Sting ability grants you 25% and consuming Rapid Killing grants you 50% of your Mana regeneration while casting for the next 15 sec.", "Hitting a target with your Serpent Sting ability grants you 50% and consuming Rapid Killing grants you 100% of your Mana regeneration while casting for the next 15 sec." },
	{ "Increases the damage done by your Multi-Shot, Aimed Shot, and Volley abilities by 3%.", "Increases the damage done by your Multi-Shot, Aimed Shot, and Volley abilities by 7%.", "Increases the damage done by your Multi-Shot, Aimed Shot, and Volley abilities by 10%." },
	{ "A short-range shot that deals 50% weapon damage and disorients the target for 4 sec. Any damage caused will remove the effect. Turns off your attack when used.", cost = "8% of base mana | 15 yd range | Instant | 30 sec cooldown" },
	{ "Increases the damage you deal with ranged weapons by 1%.", "Increases the damage you deal with ranged weapons by 2%.", "Increases the damage you deal with ranged weapons by 3%.", "Increases the damage you deal with ranged weapons by 4%.", "Increases the damage you deal with ranged weapons by 5%." },
	{ "A steady snipe that increases ranged damage by 160.", cost = "365 Mana | 8-35 yd range | 4 sec cast | 15 sec cooldown" },
},
[362] = {
	{ "While tracking Beasts, Demons, Dragonkin, Elementals, Giants, Humanoids, or Undead, all damage you deal to the tracked creature type is increased by 1%.", "While tracking Beasts, Demons, Dragonkin, Elementals, Giants, Humanoids, or Undead, all damage you deal to the tracked creature type is increased by 2%.", "While tracking Beasts, Demons, Dragonkin, Elementals, Giants, Humanoids, or Undead, all damage you deal to the tracked creature type is increased by 3%.", "While tracking Beasts, Demons, Dragonkin, Elementals, Giants, Humanoids, or Undead, all damage you deal to the tracked creature type is increased by 4%.", "While tracking Beasts, Demons, Dragonkin, Elementals, Giants, Humanoids, or Undead, all damage you deal to the tracked creature type is increased by 5%." },
	{ "Increases your Parry chance by 2%.", "Increases your Parry chance by 4%.", "Increases your Parry chance by 6%.", "Increases your Parry chance by 8%.", "Increases your Parry chance by 10%." },
	{ "When your traps are triggered, all affected targets are Entrapped, preventing them from moving for 1 sec.", "When your traps are triggered, all affected targets are Entrapped, preventing them from moving for 2 sec.", "When your traps are triggered, all affected targets are Entrapped, preventing them from moving for 3 sec.", "When your traps are triggered, all affected targets are Entrapped, preventing them from moving for 4 sec.", "When your traps are triggered, all affected targets are Entrapped, preventing them from moving for 5 sec." },
	{ "Increases the critical strike chance of all your melee abilities by 2%.", "Increases the critical strike chance of all your melee abilities by 4%." },
	{ "Increases your total Health by 2%.", "Increases your total Health by 4%.", "Increases your total Health by 6%.", "Increases your total Health by 8%.", "Increases your total Health by 10%." },
	{ "Gives your Wing Clip ability a 7% chance to immobilize the target for 5 sec.", "Gives your Wing Clip ability a 13% chance to immobilize the target for 5 sec.", "Gives your Wing Clip ability a 20% chance to immobilize the target for 5 sec." },
	{ "Increases the duration of Freezing and Frost trap effects by 15% and the damage of Immolation and Explosive trap effects by 15%.", "Increases the duration of Freezing and Frost trap effects by 30% and the damage of Immolation and Explosive trap effects by 30%." },
	{ "Increases your hit chance by 1% and reduces the duration of movement impairing effects on you by 10%.", "Increases your hit chance by 2% and reduces the duration of movement impairing effects on you by 20%.", "Increases your hit chance by 3% and reduces the duration of movement impairing effects on you by 30%." },
	{ "When activated, increases your Dodge and Parry chance by 25% for 10 sec.", cost = "Instant | 5 min cooldown" },
	{ "Increases your chance to hit with your Trap and Feign Death abilities by 5%.", "Increases your chance to hit with your Trap and Feign Death abilities by 10%." },
	{ "Increases your melee critical strike damage by 6% and your offhand weapon damage by 10%.", "Increases your melee critical strike damage by 12% and your offhand weapon damage by 20%.", "Increases your melee critical strike damage by 18% and your offhand weapon damage by 30%.", "Increases your melee critical strike damage by 24% and your offhand weapon damage by 40%.", "Increases your melee critical strike damage by 30% and your offhand weapon damage by 50%." },
	{ "A strike that becomes active after parrying an opponent's attack. This attack deals 50% weapon damage plus 13 and immobilizes the target for 5 sec. Counterattack cannot be blocked, dodged, or parried.", cost = "30 Mana | Melee Range | Instant | 5 sec cooldown" },
	{ "Reduces the mana cost of your Trap abilities and melee abilities by 30%. In addition, your critical strikes have a 30% chance to allow 50% of your Mana regeneration to continue while casting for 30 sec.", "Reduces the mana cost of your Trap abilities and melee abilities by 60%. In addition, your critical strikes have a 60% chance to allow 50% of your Mana regeneration to continue while casting for 30 sec." },
	{ "Your attacks against targets with Hunter's Mark have a 5% chance to activate your Mongoose Bite for 5 sec.", "Your attacks against targets with Hunter's Mark have a 10% chance to activate your Mongoose Bite for 5 sec." },
	{ "Reduces the cooldown of your Trap and Deterrence abilities by 20%.", "Reduces the cooldown of your Trap and Deterrence abilities by 40%." },
	{ "A powerful kick that deals 100% melee weapon damage and increases movement speed by 30% for 3 sec.", cost = "5.81% of base mana | Melee Range | Instant | 8 sec cooldown" },
	{ "Increases your Agility by 2%.", "Increases your Agility by 4%.", "Increases your Agility by 6%.", "Increases your Agility by 8%.", "Increases your Agility by 10%." },
	{ "Your Mongoose Bite also causes the target to Bleed for damage over 21 sec equal to 40% of the damage done by Mongoose Bite." },
},
[182] = {
	{ "Increases the duration of your Gouge ability by 0.5 sec.", "Increases the duration of your Gouge ability by 1 sec.", "Increases the duration of your Gouge ability by 1.5 sec." },
	{ "After killing a non-trivial enemy, gives you a 20% increased critical strike chance on your next Sinister Strike, Backstab, Ambush, Mutilate, or Ghostly Strike. Lasts 20 sec.", "After killing a non-trivial enemy, gives you a 40% increased critical strike chance on your next Sinister Strike, Backstab, Ambush, Mutilate, or Ghostly Strike. Lasts 20 sec." },
	{ "Increases your critical strike chance with all attacks and Poisons by 1%.", "Increases your critical strike chance with all attacks and Poisons by 2%.", "Increases your critical strike chance with all attacks and Poisons by 3%.", "Increases your critical strike chance with all attacks and Poisons by 4%.", "Increases your critical strike chance with all attacks and Poisons by 5%." },
	{ "Gives your finishing moves a 20% chance to add a Combo Point to your target.", "Gives your finishing moves a 40% chance to add a Combo Point to your target.", "Gives your finishing moves a 60% chance to add a Combo Point to your target." },
	{ "Increases all damage dealt by 2% against Humanoid and Giant targets.", "Increases all damage dealt by 4% against Humanoid and Giant targets." },
	{ "Increases the duration of your Slice and Dice ability by 15%.", "Increases the duration of your Slice and Dice ability by 30%.", "Increases the duration of your Slice and Dice ability by 45%." },
	{ "Your finishing moves have a 20% chance per Combo Point to restore 25 Energy." },
	{ "Reduces the Energy cost of your Expose Armor ability by 5, and refunds 1 Combo Point when cast with 5 Combo Points.", "Reduces the Energy cost of your Expose Armor ability by 10, and refunds 2 Combo Points when cast with 5 Combo Points." },
	{ "Increases the critical strike damage bonus of your Sinister Strike, Gouge, Backstab, Mutilate, Ghostly Strike, and Hemorrhage abilities by 4%.", "Increases the critical strike damage bonus of your Sinister Strike, Gouge, Backstab, Mutilate, Ghostly Strike, and Hemorrhage abilities by 8%.", "Increases the critical strike damage bonus of your Sinister Strike, Gouge, Backstab, Mutilate, Ghostly Strike, and Hemorrhage abilities by 12%.", "Increases the critical strike damage bonus of your Sinister Strike, Gouge, Backstab, Mutilate, Ghostly Strike, and Hemorrhage abilities by 16%.", "Increases the critical strike damage bonus of your Sinister Strike, Gouge, Backstab, Mutilate, Ghostly Strike, and Hemorrhage abilities by 20%." },
	{ "Increases the damage dealt by your poisons by 4% and gives your poisons an additional 8% chance to resist dispel effects.", "Increases the damage dealt by your poisons by 8% and gives your poisons an additional 16% chance to resist dispel effects.", "Increases the damage dealt by your poisons by 12% and gives your poisons an additional 24% chance to resist dispel effects.", "Increases the damage dealt by your poisons by 16% and gives your poisons an additional 32% chance to resist dispel effects.", "Increases the damage dealt by your poisons by 20% and gives your poisons an additional 40% chance to resist dispel effects." },
	{ "When activated, increases the critical strike chance of your next Sinister Strike, Backstab, Ambush, Eviscerate, or Mutilate by 100%.", cost = "Instant | 3 min cooldown" },
	{ "Increases the chance to apply Poisons to your target by 2%, and gives Poison applications a 10% chance to not consume a charge.", "Increases the chance to apply Poisons to your target by 4%, and gives Poison applications a 20% chance to not consume a charge.", "Increases the chance to apply Poisons to your target by 6%, and gives Poison applications a 30% chance to not consume a charge.", "Increases the chance to apply Poisons to your target by 8%, and gives Poison applications a 40% chance to not consume a charge.", "Increases the chance to apply Poisons to your target by 10%, and gives Poison applications a 50% chance to not consume a charge." },
	{ "Increases your maximum Energy by 5.", "Increases your maximum Energy by 10." },
	{ "Instantly attacks with both weapons for 75% weapon damage plus an additional 13 with each weapon. Damage increased by 20% against Poisoned targets. Awards 2 Combo Points.", cost = "60 Energy | Melee Range | Instant | Requires Daggers" },
	{ "Enemies Stunned by your Kidney Shot ability take 5% increased damage from your poisons and attacks.", "Enemies Stunned by your Kidney Shot ability take 10% increased damage from your poisons and attacks." },
	{ "Your critical strikes from abilities that add Combo Points have a 20% chance to add an additional Combo Point.", "Your critical strikes from abilities that add Combo Points have a 40% chance to add an additional Combo Point.", "Your critical strikes from abilities that add Combo Points have a 60% chance to add an additional Combo Point.", "Your critical strikes from abilities that add Combo Points have a 80% chance to add an additional Combo Point.", "Your critical strikes from abilities that add Combo Points have a 100% chance to add an additional Combo Point." },
	{ "Finishing move that increases the damage of your Poisons by 30% and your chance to apply Poisons by 10%. Lasts longer per combo point:\n 1 point : 9 seconds\n 2 points: 12 seconds\n 3 points: 15 seconds\n 4 points: 18 seconds\n 5 points: 21 seconds", cost = "25 Energy | 100 yd range | Instant" },
},
[181] = {
	{ "Increases the damage done by your Eviscerate ability by 7%.", "Increases the damage done by your Eviscerate ability by 13%.", "Increases the damage done by your Eviscerate ability by 20%." },
	{ "Reduces the Energy cost of your Sinister Strike ability by 3.", "Reduces the Energy cost of your Sinister Strike ability by 5." },
	{ "Increases your Dodge chance by 1%.", "Increases your Dodge chance by 2%.", "Increases your Dodge chance by 3%.", "Increases your Dodge chance by 4%.", "Increases your Dodge chance by 5%." },
	{ "Increases the critical strike chance of your Backstab by 10% and your Mutilate by 5%, and gives Backstab a 15% chance to add an additional Combo Point.", "Increases the critical strike chance of your Backstab by 20% and your Mutilate by 10%, and gives Backstab a 30% chance to add an additional Combo Point.", "Increases the critical strike chance of your Backstab by 30% and your Mutilate by 15%, and gives Backstab a 45% chance to add an additional Combo Point." },
	{ "Increases your Parry chance by 2%.", "Increases your Parry chance by 4%.", "Increases your Parry chance by 6%." },
	{ "Improves your chance to hit by 1%.", "Improves your chance to hit by 2%.", "Improves your chance to hit by 3%." },
	{ "Reduces the cooldown of your Sprint and Evasion abilities by 30%.", "Reduces the cooldown of your Sprint and Evasion abilities by 60%." },
	{ "A strike that becomes active after parrying an opponent's attack. This attack deals 150% weapon damage and disarms the target for 6 sec.", cost = "10 Energy | Melee Range | Instant | 6 sec cooldown" },
	{ "Gives a 50% chance to remove all movement impairing effects when you activate your Sprint ability.", "Gives a 100% chance to remove all movement impairing effects when you activate your Sprint ability." },
	{ "Gives your Kick ability a 50% chance to Silence the target for 2 sec.", "Gives your Kick ability a 100% chance to Silence the target for 2 sec." },
	{ "Reduces the Energy cost of your Eviscerate ability by 10." },
	{ "Increases the damage done by your off-hand weapon by 5%.", "Increases the damage done by your off-hand weapon by 10%.", "Increases the damage done by your off-hand weapon by 15%.", "Increases the damage done by your off-hand weapon by 20%.", "Increases the damage done by your off-hand weapon by 25%." },
	{ "Increases your melee attack speed by 20% and your melee attacks strike an additional nearby opponent. Lasts 15 sec.", cost = "25 Energy | Instant | 2 min cooldown" },
	{ "Gives your melee weapon attacks a benefit depending on the weapon.\n\n Axe/Sword: Your successful\n melee attacks have a 1% chance\n to trigger an extra attack on the \n target.\n\n Dagger/Fist: Increases your\n critical strike chance by 1%.\n\n Mace: Your attacks ignore 3% of\n your target's armor.", "Gives your melee weapon attacks a benefit depending on the weapon.\n\n Axe/Sword: Your successful\n melee attacks have a 2% chance\n to trigger an extra attack on the \n target.\n\n Dagger/Fist: Increases your\n critical strike chance by 2%.\n\n Mace: Your attacks ignore 6% of\n your target's armor.", "Gives your melee weapon attacks a benefit depending on the weapon.\n\n Axe/Sword: Your successful\n melee attacks have a 3% chance\n to trigger an extra attack on the \n target.\n\n Dagger/Fist: Increases your\n critical strike chance by 3%.\n\n Mace: Your attacks ignore 9% of\n your target's armor.", "Gives your melee weapon attacks a benefit depending on the weapon.\n\n Axe/Sword: Your successful\n melee attacks have a 4% chance\n to trigger an extra attack on the \n target.\n\n Dagger/Fist: Increases your\n critical strike chance by 4%.\n\n Mace: Your attacks ignore 12% of\n your target's armor.", "Gives your melee weapon attacks a benefit depending on the weapon.\n\n Axe/Sword: Your successful\n melee attacks have a 5% chance\n to trigger an extra attack on the \n target.\n\n Dagger/Fist: Increases your\n critical strike chance by 5%.\n\n Mace: Your attacks ignore 15% of\n your target's armor." },
	{ "Reduces the chance for your attacks to be Dodged or Parried by 1%.", "Reduces the chance for your attacks to be Dodged or Parried by 2%." },
	{ "Increases the damage of your Sinister Strike, Backstab, and Eviscerate abilities by 2%.", "Increases the damage of your Sinister Strike, Backstab, and Eviscerate abilities by 4%.", "Increases the damage of your Sinister Strike, Backstab, and Eviscerate abilities by 6%." },
	{ "Increases your Energy regeneration rate by 100% for 15 sec.", cost = "Instant | 5 min cooldown" },
},
[183] = {
	{ "Reduces your speed penalty from your Stealth ability by 3% and reduces its cooldown by 2 sec.", "Reduces your speed penalty from your Stealth ability by 6% and reduces its cooldown by 3 sec.", "Reduces your speed penalty from your Stealth ability by 9% and reduces its cooldown by 4 sec.", "Reduces your speed penalty from your Stealth ability by 12% and reduces its cooldown by 5 sec.", "Reduces your speed penalty from your Stealth ability by 15% and reduces its cooldown by 6 sec." },
	{ "Reduces the chance enemies have to detect you while in Stealth mode as if you were 1 level higher.", "Reduces the chance enemies have to detect you while in Stealth mode as if you were 2 levels higher.", "Reduces the chance enemies have to detect you while in Stealth mode as if you were 3 levels higher." },
	{ "Increases the damage dealt by your Backstab, Garrote, Ambush, and Mutilate abilities by 5%.", "Increases the damage dealt by your Backstab, Garrote, Ambush, and Mutilate abilities by 10%." },
	{ "Gives you a 33% chance to add a Combo Point to your target after Dodging an attack or fully resisting a spell.", "Gives you a 67% chance to add a Combo Point to your target after Dodging an attack or fully resisting a spell.", "Gives you a 100% chance to add a Combo Point to your target after Dodging an attack or fully resisting a spell." },
	{ "Reduces the cooldown of your Vanish and Blind abilities by 45 sec.", "Reduces the cooldown of your Vanish and Blind abilities by 90 sec." },
	{ "Reduces the Energy cost of your Sap and Blind abilities by 25%.", "Reduces the Energy cost of your Sap and Blind abilities by 50%." },
	{ "Increases the critical strike chance of your Ambush ability by 15%.", "Increases the critical strike chance of your Ambush ability by 30%.", "Increases the critical strike chance of your Ambush ability by 45%." },
	{ "Gives you a 33% chance to add an additional combo point to your target when using your Ambush, Garrote, or Cheap Shot ability.", "Gives you a 67% chance to add an additional combo point to your target when using your Ambush, Garrote, or Cheap Shot ability.", "Gives you a 100% chance to add an additional combo point to your target when using your Ambush, Garrote, or Cheap Shot ability." },
	{ "A strike that deals 125% (180% if a Dagger is equipped in your Main Hand) weapon damage and increases your chance to dodge by 15% for 7 sec. Awards 1 combo point.", cost = "40 Energy | Melee Range | Instant | 20 sec cooldown" },
	{ "Increases the radius of your Distract ability by 3 yds, and further reduces the Stealth detection of distracted enemies as though they were an additional 1 level lower.", "Increases the radius of your Distract ability by 5 yds, and further reduces the Stealth detection of distracted enemies as though they were an additional 2 levels lower." },
	{ "Increases your Stealth detection as if you were 1 level higher and reduces your chance to be hit by spells and ranged attacks by 2%.", "Increases your Stealth detection as if you were 3 levels higher and reduces your chance to be hit by spells and ranged attacks by 4%." },
	{ "Adds 2 Combo Points to your target. You must add to or use those combo points within 20 sec or the combo points are lost.", cost = "20 yd range | Instant | 2 min cooldown" },
	{ "Causes your attacks to ignore 3% of your target's Armor and increases the damage dealt by your Rupture ability by 10%.", "Causes your attacks to ignore 6% of your target's Armor and increases the damage dealt by your Rupture ability by 20%.", "Causes your attacks to ignore 9% of your target's Armor and increases the damage dealt by your Rupture ability by 30%." },
	{ "Reduces the Energy cost of your Cheap Shot and Garrote abilities by 10, and your Garrote ability no longer requires you to be behind your target.", "Reduces the Energy cost of your Cheap Shot and Garrote abilities by 20, and your Garrote ability no longer requires you to be behind your target." },
	{ "When activated, this ability immediately finishes the cooldown on your other Rogue abilities.", cost = "Instant | 10 min cooldown" },
	{ "An instant strike that deals 100% weapon damage (145% if a Dagger is equipped) and causes the target to take 15% increased Rupture damage from the Rogue. Lasts 15 sec. Awards 1 Combo Point.", cost = "35 Energy | Melee Range | Instant" },
	{ "Your Sinister Strike, Ghostly Strike, and Hemorrhage abilities cause 2% more damage against targets below 35% health.", "Your Sinister Strike, Ghostly Strike, and Hemorrhage abilities cause 4% more damage against targets below 35% health.", "Your Sinister Strike, Ghostly Strike, and Hemorrhage abilities cause 6% more damage against targets below 35% health.", "Your Sinister Strike, Ghostly Strike, and Hemorrhage abilities cause 8% more damage against targets below 35% health.", "Your Sinister Strike, Ghostly Strike, and Hemorrhage abilities cause 10% more damage against targets below 35% health." },
	{ "Your Backstab has a 3% chance to cause your next Ambush within 10 sec to not require Stealth.", "Your Backstab has a 6% chance to cause your next Ambush within 10 sec to not require Stealth.", "Your Backstab has a 9% chance to cause your next Ambush within 10 sec to not require Stealth.", "Your Backstab has a 12% chance to cause your next Ambush within 10 sec to not require Stealth.", "Your Backstab has a 15% chance to cause your next Ambush within 10 sec to not require Stealth." },
	{ "When your Rupture ability deals periodic damage, the Energy cost of your next Hemorrhage or Backstab ability within 10 sec is reduced by 3, stacking up to 5 times." },
},
[201] = {
	{ "Your Smite and Penance spells deal 2% increased damage to targets afflicted with your Holy Fire.", "Your Smite and Penance spells deal 4% increased damage to targets afflicted with your Holy Fire.", "Your Smite and Penance spells deal 6% increased damage to targets afflicted with your Holy Fire.", "Your Smite and Penance spells deal 8% increased damage to targets afflicted with your Holy Fire.", "Your Smite and Penance spells deal 10% increased damage to targets afflicted with your Holy Fire." },
	{ "Increases your damage with Wands by 13%.", "Increases your damage with Wands by 25%." },
	{ "Increases the damage and healing of your instant cast spells by 1%.", "Increases the damage and healing of your instant cast spells by 2%.", "Increases the damage and healing of your instant cast spells by 3%.", "Increases the damage and healing of your instant cast spells by 4%.", "Increases the damage and healing of your instant cast spells by 5%." },
	{ "Reduces the threat generated by your Holy spells by 10% and reduces the duration of Stun, Fear, and Silence effects inflicted on you by 5%.", "Reduces the threat generated by your Holy spells by 20% and reduces the duration of Stun, Fear, and Silence effects inflicted on you by 10%.", "Reduces the threat generated by your Holy spells by 30% and reduces the duration of Stun, Fear, and Silence effects inflicted on you by 15%." },
	{ "Improves your chance to hit with Holy spells by 6%.", "Improves your chance to hit with Holy spells by 12%.", "Improves your chance to hit with Holy spells by 18%." },
	{ "Increases the damage absorbed by your Power Word: Shield by 7%.", "Increases the damage absorbed by your Power Word: Shield by 14%.", "Increases the damage absorbed by your Power Word: Shield by 20%." },
	{ "Gives you a 50% chance to gain Focused Casting for 6 sec after being the victim of a melee or ranged critical strike. The Focused Casting effect prevents you from losing casting time when taking damage and increases your resistance to Interrupt effects by 20%.", "Gives you a 100% chance to gain Focused Casting for 6 sec after being the victim of a melee or ranged critical strike. The Focused Casting effect prevents you from losing casting time when taking damage and increases your resistance to Interrupt effects by 20%." },
	{ "Reduces the mana cost of your Smite, Holy Fire, and instant cast spells by 3%.", "Reduces the mana cost of your Smite, Holy Fire, and instant cast spells by 7%.", "Reduces the mana cost of your Smite, Holy Fire, and instant cast spells by 10%." },
	{ "When activated, reduces the Mana cost of your next spell by 100% and increases its critical effect chance by 25% if it is capable of a critical effect.", cost = "Instant | 3 min cooldown" },
	{ "Allows 17% of your Mana regeneration to continue while casting.", "Allows 33% of your Mana regeneration to continue while casting.", "Allows 50% of your Mana regeneration to continue while casting." },
	{ "Increases the Armor bonus of your Inner Fire spell by 15% and increases its total charges by 4.", "Increases the Armor bonus of your Inner Fire spell by 30% and increases its total charges by 8.", "Increases the Armor bonus of your Inner Fire spell by 45% and increases its total charges by 12." },
	{ "Increases your total Intellect by 3%.", "Increases your total Intellect by 6%.", "Increases your total Intellect by 9%.", "Increases your total Intellect by 12%.", "Increases your total Intellect by 15%." },
	{ "Reduces the cooldown on your Power Word: Shield spell by 4 sec and reduces its mana cost by 15%." },
	{ "Reduces the casting time of your Mana Burn spell by 0.5 sec.", "Reduces the casting time of your Mana Burn spell by 1 sec." },
	{ "Launches a volley of holy light at the target, causing 81 Holy damage to an enemy, or 184 healing to an ally, instantly and every 1 sec for 2 sec.", cost = "100 Mana | 40 yd range | Channeled | 12 sec cooldown" },
	{ "Your heals from Flash Heal, Binding Heal, Lesser Heal, Heal, Greater Heal, and Penance gain 2% increased critical strike chance when cast on targets with Weakened Soul, and reduce the remaining duration of Weakened Soul on their target by 1 sec.", "Your heals from Flash Heal, Binding Heal, Lesser Heal, Heal, Greater Heal, and Penance gain 4% increased critical strike chance when cast on targets with Weakened Soul, and reduce the remaining duration of Weakened Soul on their target by 2 sec.", "Your heals from Flash Heal, Binding Heal, Lesser Heal, Heal, Greater Heal, and Penance gain 6% increased critical strike chance when cast on targets with Weakened Soul, and reduce the remaining duration of Weakened Soul on their target by 3 sec.", "Your heals from Flash Heal, Binding Heal, Lesser Heal, Heal, Greater Heal, and Penance gain 8% increased critical strike chance when cast on targets with Weakened Soul, and reduce the remaining duration of Weakened Soul on their target by 4 sec.", "Your heals from Flash Heal, Binding Heal, Lesser Heal, Heal, Greater Heal, and Penance gain 10% increased critical strike chance when cast on targets with Weakened Soul, and reduce the remaining duration of Weakened Soul on their target by 5 sec." },
	{ "Your critical heals create a protective shield on the target, absorbing 5% of the amount healed. Lasts 12 sec.", "Your critical heals create a protective shield on the target, absorbing 10% of the amount healed. Lasts 12 sec.", "Your critical heals create a protective shield on the target, absorbing 15% of the amount healed. Lasts 12 sec." },
	{ "Infuses the target with power, increasing their spell damage and healing done by 20% for 15 sec.", cost = "20% of base mana | 30 yd range | Instant | 3 min cooldown" },
},
[202] = {
	{ "Gives you a 23% chance to avoid interruption caused by damage while casting any spell.", "Gives you a 47% chance to avoid interruption caused by damage while casting any spell.", "Gives you a 70% chance to avoid interruption caused by damage while casting any spell." },
	{ "Increases the amount healed by your Renew spell by 5%.", "Increases the amount healed by your Renew spell by 10%.", "Increases the amount healed by your Renew spell by 15%." },
	{ "Increases the critical effect chance of your Holy spells by 1%.", "Increases the critical effect chance of your Holy spells by 2%.", "Increases the critical effect chance of your Holy spells by 3%.", "Increases the critical effect chance of your Holy spells by 4%.", "Increases the critical effect chance of your Holy spells by 5%." },
	{ "Reduces all spell damage taken by 2%.", "Reduces all spell damage taken by 4%.", "Reduces all spell damage taken by 6%.", "Reduces all spell damage taken by 8%.", "Reduces all spell damage taken by 10%." },
	{ "Reduces the casting time of your Smite, Holy Fire, Heal, and Greater Heal spells by 0.1 sec.", "Reduces the casting time of your Smite, Holy Fire, Heal, and Greater Heal spells by 0.2 sec.", "Reduces the casting time of your Smite, Holy Fire, Heal, and Greater Heal spells by 0.3 sec.", "Reduces the casting time of your Smite, Holy Fire, Heal, and Greater Heal spells by 0.4 sec.", "Reduces the casting time of your Smite, Holy Fire, Heal, and Greater Heal spells by 0.5 sec." },
	{ "Causes an explosion of holy light around the caster, causing 26 to 30 Holy damage to all enemy targets within 10 yards and healing all party members within 10 yards for 49 to 57. These effects cause no threat.", cost = "185 Mana | Instant" },
	{ "After being struck by a melee or ranged critical hit, or suffering more than 30% of your maximum Health from a single attack, heal 8% of the damage taken over 6 sec. Refreshing this effect carries over any remaining healing.", "After being struck by a melee or ranged critical hit, or suffering more than 30% of your maximum Health from a single attack, heal 17% of the damage taken over 6 sec. Refreshing this effect carries over any remaining healing.", "After being struck by a melee or ranged critical hit, or suffering more than 30% of your maximum Health from a single attack, heal 25% of the damage taken over 6 sec. Refreshing this effect carries over any remaining healing." },
	{ "Your non-periodic critical heals increase your target's Armor by 8% for 15 sec.", "Your non-periodic critical heals increase your target's Armor by 17% for 15 sec.", "Your non-periodic critical heals increase your target's Armor by 25% for 15 sec." },
	{ "Increases the range of your Smite and Holy Fire spells and the radius of your Prayer of Healing and Holy Nova spells by 10%.", "Increases the range of your Smite and Holy Fire spells and the radius of your Prayer of Healing and Holy Nova spells by 20%." },
	{ "Reduces the Mana cost of your Lesser Heal, Heal, Greater Heal, Penance, and Prayer of Mending spells by 5%.", "Reduces the Mana cost of your Lesser Heal, Heal, Greater Heal, Penance, and Prayer of Mending spells by 10%.", "Reduces the Mana cost of your Lesser Heal, Heal, Greater Heal, Penance, and Prayer of Mending spells by 15%." },
	{ "Increases your Holy damage done by 2%, and gives a 5% chance each time your Holy Fire spell deals periodic damage for your next Holy Nova to cost no Mana.", "Increases your Holy damage done by 5%, and gives a 10% chance each time your Holy Fire spell deals periodic damage for your next Holy Nova to cost no Mana." },
	{ "Heals a friendly target and the caster for 236 to 284. Low threat.", cost = "155 Mana | 40 yd range | 1.5 sec cast" },
	{ "When you cast a healing spell, gain Mana equal to 5% of the base cost of the spell if your previous heal was a different spell.", "When you cast a healing spell, gain Mana equal to 10% of the base cost of the spell if your previous heal was a different spell." },
	{ "Upon death, the priest becomes the Spirit of Redemption for 15 sec. The Spirit of Redemption cannot move, attack, be attacked or targeted by any spells or effects. While in this form the priest can cast any healing spell free of cost. When the effect ends, the priest dies." },
	{ "Increases your spell healing by up to 5% of your total Spirit and your spell damage by up to 1% of your total Spirit.", "Increases your spell healing by up to 10% of your total Spirit and your spell damage by up to 3% of your total Spirit.", "Increases your spell healing by up to 15% of your total Spirit and your spell damage by up to 5% of your total Spirit.", "Increases your spell healing by up to 20% of your total Spirit and your spell damage by up to 6% of your total Spirit.", "Increases your spell healing by up to 25% of your total Spirit and your spell damage by up to 8% of your total Spirit." },
	{ "Increases the amount healed by your spells by 3%.", "Increases the amount healed by your spells by 7%.", "Increases the amount healed by your spells by 10%." },
	{ "Places a spell on the target that heals them for 172 the next time they take damage or receive non-periodic healing. When the heal occurs, Prayer of Mending jumps to a party or raid member within 20 yards. Jumps up to 5 times and lasts 30 sec after each jump. This spell can only be placed on one target at a time per caster.", cost = "210 Mana | 40 yd range | Instant | 10 sec cooldown" },
},
[203] = {
	{ "Improves your chance to hit with Shadow spells by 1%.", "Improves your chance to hit with Shadow spells by 2%.", "Improves your chance to hit with Shadow spells by 3%.", "Improves your chance to hit with Shadow spells by 4%.", "Improves your chance to hit with Shadow spells by 5%." },
	{ "Gives your Shadow damage spells a 2% chance to stun the target for 3 sec.", "Gives your Shadow damage spells a 4% chance to stun the target for 3 sec.", "Gives your Shadow damage spells a 6% chance to stun the target for 3 sec.", "Gives your Shadow damage spells a 8% chance to stun the target for 3 sec.", "Gives your Shadow damage spells a 10% chance to stun the target for 3 sec." },
	{ "Gives you a 20% chance to gain a 100% bonus to your Spirit for 15 sec after killing a non-trivial target. For the duration, your Mana will regenerate at a 50% of normal rate while casting.", "Gives you a 40% chance to gain a 100% bonus to your Spirit for 15 sec after killing a non-trivial target. For the duration, your Mana will regenerate at a 50% of normal rate while casting.", "Gives you a 60% chance to gain a 100% bonus to your Spirit for 15 sec after killing a non-trivial target. For the duration, your Mana will regenerate at a 50% of normal rate while casting.", "Gives you a 80% chance to gain a 100% bonus to your Spirit for 15 sec after killing a non-trivial target. For the duration, your Mana will regenerate at a 50% of normal rate while casting.", "Gives you a 100% chance to gain a 100% bonus to your Spirit for 15 sec after killing a non-trivial target. For the duration, your Mana will regenerate at a 50% of normal rate while casting." },
	{ "Reduces the threat generated by your Shadow spells by 10%.", "Reduces the threat generated by your Shadow spells by 20%.", "Reduces the threat generated by your Shadow spells by 30%." },
	{ "Increases the duration of your Shadow Word: Pain spell by 3 sec.", "Increases the duration of your Shadow Word: Pain spell by 6 sec." },
	{ "Increases the range of your offensive Shadow spells by 10%.", "Increases the range of your offensive Shadow spells by 20%." },
	{ "Reduces the cooldown of your Mind Blast spell by 0.5 sec.", "Reduces the cooldown of your Mind Blast spell by 1 sec.", "Reduces the cooldown of your Mind Blast spell by 1.5 sec.", "Reduces the cooldown of your Mind Blast spell by 2 sec.", "Reduces the cooldown of your Mind Blast spell by 2.5 sec." },
	{ "Reduces the cooldown of your Psychic Scream spell by 2 sec.", "Reduces the cooldown of your Psychic Scream spell by 4 sec." },
	{ "Assault the target's mind with Shadow energy, causing 63 Shadow damage over 3 sec and slowing their movement speed by 50%.", cost = "45 Mana | 20 yd range | Channeled" },
	{ "Your Mind Flay now deals 10% more damage, gains 5 yards increased range, but slows the target's movement speed by 35%.", "Your Mind Flay now deals 20% more damage, gains 10 yards increased range, but slows the target's movement speed by 20%." },
	{ "Decreases the cooldown of your Fade ability by 3 sec.", "Decreases the cooldown of your Fade ability by 6 sec." },
	{ "Afflicts your target with Shadow energy that causes all party members to be healed for 20% of any Shadow spell damage you deal for 30 sec. Vampiric Embrace also grants a chance for your Spirit Tap talent to trigger when enemies afflicted by it die.", cost = "40 Mana | 30 yd range | Instant | 1 min cooldown" },
	{ "Your Shadow damage spells have a 33% chance to increase the Shadow damage you deal by 2% for 15 sec, stacking up to 5 times.", "Your Shadow damage spells have a 67% chance to increase the Shadow damage you deal by 2% for 15 sec, stacking up to 5 times.", "Your Shadow damage spells have a 100% chance to increase the Shadow damage you deal by 2% for 15 sec, stacking up to 5 times." },
	{ "Silences the target, preventing them from casting spells for 5 sec and interrupting their spellcasts for 3 sec.", cost = "225 Mana | 20 yd range | Instant | 45 sec cooldown" },
	{ "Reduces the mana cost of your Devouring Plague by 25%.\n\nTargets that die while Devouring Plague is active spreads it, jumping to a nearby enemy within 5 yards for the remaining duration.", "Reduces the mana cost of your Devouring Plague by 50%.\n\nTargets that die while Devouring Plague is active spreads it, jumping to a nearby enemy within 10 yards for the remaining duration." },
	{ "Increases Shadow Word: Death's critical strike chance on targets at or below 20% health by 15%.", "Increases Shadow Word: Death's critical strike chance on targets at or below 20% health by 30%." },
	{ "Increases your Shadow damage done by 2%.", "Increases your Shadow damage done by 4%.", "Increases your Shadow damage done by 6%.", "Increases your Shadow damage done by 8%.", "Increases your Shadow damage done by 10%." },
	{ "Assume Shadowform, increasing your Shadow damage by 10%, reducing the Mana cost of all Shadow spells by 50%, increasing the critical strike damage bonus of your Shadow spells by 100%, and reducing Physical damage taken by you by 15%. However, you may not cast healing spells while in this form.", cost = "40% of base mana | Instant | 1.5 sec cooldown" },
},
[261] = {
	{ "Reduces the mana cost of your Shock, Lightning Bolt, Lava Burst, and Chain Lightning spells by 2%.", "Reduces the mana cost of your Shock, Lightning Bolt, Lava Burst, and Chain Lightning spells by 4%.", "Reduces the mana cost of your Shock, Lightning Bolt, Lava Burst, and Chain Lightning spells by 6%.", "Reduces the mana cost of your Shock, Lightning Bolt, Lava Burst, and Chain Lightning spells by 8%.", "Reduces the mana cost of your Shock, Lightning Bolt, Lava Burst, and Chain Lightning spells by 10%." },
	{ "Increases the damage done by your Lightning Bolt, Chain Lightning, and Earth Shock spells by 1%.", "Increases the damage done by your Lightning Bolt, Chain Lightning, and Earth Shock spells by 2%.", "Increases the damage done by your Lightning Bolt, Chain Lightning, and Earth Shock spells by 3%.", "Increases the damage done by your Lightning Bolt, Chain Lightning, and Earth Shock spells by 4%.", "Increases the damage done by your Lightning Bolt, Chain Lightning, and Earth Shock spells by 5%." },
	{ "Reduces damage taken from Fire, Frost, and Nature effects by 3%.", "Reduces damage taken from Fire, Frost, and Nature effects by 7%.", "Reduces damage taken from Fire, Frost, and Nature effects by 10%." },
	{ "Reduces the cooldown of your Shock spells by 0.2 sec.", "Reduces the cooldown of your Shock spells by 0.4 sec.", "Reduces the cooldown of your Shock spells by 0.6 sec.", "Reduces the cooldown of your Shock spells by 0.8 sec.", "Reduces the cooldown of your Shock spells by 1 sec." },
	{ "Increases the damage done by your Fire Totems and by your Flame Shock, Fire Nova, and Lava Burst spells by 5%.", "Increases the damage done by your Fire Totems and by your Flame Shock, Fire Nova, and Lava Burst spells by 10%.", "Increases the damage done by your Fire Totems and by your Flame Shock, Fire Nova, and Lava Burst spells by 15%." },
	{ "Your offensive spell critical strikes will increase your chance to get a critical strike with melee attacks by 3% for 10 sec.", "Your offensive spell critical strikes will increase your chance to get a critical strike with melee attacks by 6% for 10 sec.", "Your offensive spell critical strikes will increase your chance to get a critical strike with melee attacks by 9% for 10 sec." },
	{ "Gives you a 10% chance to enter a Clearcasting state after casting any Fire, Frost, or Nature damage spell. The Clearcasting state reduces the mana cost of your next damage spell by 100%." },
	{ "Reduces the cast time of your Lightning Bolt, Chain Lightning, and Lava Burst spells by 0.17 sec.", "Reduces the cast time of your Lightning Bolt, Chain Lightning, and Lava Burst spells by 0.33 sec.", "Reduces the cast time of your Lightning Bolt, Chain Lightning, and Lava Burst spells by 0.50 sec." },
	{ "Increases the damage done by your Fire Nova spell by 10% and reduces its cooldown by 2 sec.", "Increases the damage done by your Fire Nova spell by 20% and reduces its cooldown by 4 sec." },
	{ "Reduces the pushback suffered from damaging attacks while casting Lightning Bolt, Chain Lightning, and Lava Burst by 23%.", "Reduces the pushback suffered from damaging attacks while casting Lightning Bolt, Chain Lightning, and Lava Burst by 47%.", "Reduces the pushback suffered from damaging attacks while casting Lightning Bolt, Chain Lightning, and Lava Burst by 70%." },
	{ "Increases the critical strike chance of your Lightning Bolt and Chain Lightning spells by 3%." },
	{ "Increases the range of your Lightning Bolt, Chain Lightning, Fire Nova, and Lava Burst spells by 3 yards, and increases the range of your Flame Shock spell by 8 yards.", "Increases the range of your Lightning Bolt, Chain Lightning, Fire Nova, and Lava Burst spells by 6 yards, and increases the range of your Flame Shock spell by 15 yards." },
	{ "Gives your Lightning Bolt and Chain Lightning spells a 3% chance to cast a second, similar spell on the same target at no additional cost that causes half damage and no threat.", "Gives your Lightning Bolt and Chain Lightning spells a 7% chance to cast a second, similar spell on the same target at no additional cost that causes half damage and no threat.", "Gives your Lightning Bolt and Chain Lightning spells a 10% chance to cast a second, similar spell on the same target at no additional cost that causes half damage and no threat." },
	{ "Your Earthbind Totem Immobilizes nearby targets for 5 sec when cast." },
	{ "Increases the critical strike damage bonus of your Searing and Magma Totems and your Fire, Frost, and Nature spells by 20%.", "Increases the critical strike damage bonus of your Searing and Magma Totems and your Fire, Frost, and Nature spells by 40%.", "Increases the critical strike damage bonus of your Searing and Magma Totems and your Fire, Frost, and Nature spells by 60%.", "Increases the critical strike damage bonus of your Searing and Magma Totems and your Fire, Frost, and Nature spells by 80%.", "Increases the critical strike damage bonus of your Searing and Magma Totems and your Fire, Frost, and Nature spells by 100%." },
	{ "You hurl molten lava at the target, dealing 150 to 192 Fire damage. If your Flame Shock is on the target, Lava Burst deals 20% increased damage.", cost = "165 Mana | 30 yd range | 2.5 sec cast | 10 sec cooldown" },
},
[263] = {
