	{ "Increases the melee attack power bonus of your Rockbiter Weapon by 7%, your Windfury Weapon effect by 13% and increases the damage caused by your Flametongue Weapon and Frostbrand Weapon by 5%.", "Increases the melee attack power bonus of your Rockbiter Weapon by 13%, your Windfury Weapon effect by 27% and increases the damage caused by your Flametongue Weapon and Frostbrand Weapon by 10%.", "Increases the melee attack power bonus of your Rockbiter Weapon by 20%, your Windfury Weapon effect by 40% and increases the damage caused by your Flametongue Weapon and Frostbrand Weapon by 15%." },
	{ "Reduces the mana cost of your Shock and Lightning Shield spells by 45%." },
	{ "Increases your chance to dodge by an additional 2%.", "Increases your chance to dodge by an additional 4%.", "Increases your chance to dodge by an additional 6%." },
	{ "Increases your Stamina by 2%.", "Increases your Stamina by 4%.", "Increases your Stamina by 6%.", "Increases your Stamina by 8%.", "Increases your Stamina by 10%." },
	{ "Increases your attack speed by 5% for your next 3 swings after dealing a melee critical strike.", "Increases your attack speed by 10% for your next 3 swings after dealing a melee critical strike.", "Increases your attack speed by 15% for your next 3 swings after dealing a melee critical strike.", "Increases your attack speed by 20% for your next 3 swings after dealing a melee critical strike.", "Increases your attack speed by 25% for your next 3 swings after dealing a melee critical strike." },
	{ "Instantly strike for normal weapon damage and increase the damage you deal to the target with your next Lightning Bolt, Chain Lightning, or Earth Shock spell by 20% for 12 sec.", cost = "125 Mana | Melee Range | Instant | 8 sec cooldown" },
	{ "Gives a chance to parry enemy melee attacks, reduces all threat generated by your attacks by 30% while Rockbiter Weapon is not active, and increases all threat generated by 30% while Rockbiter Weapon is active." },
	{ "Increases your spell damage and healing by up to 15% of your Intellect.", "Increases your spell damage and healing by up to 30% of your Intellect." },
	{ "When you Stormstrike, you have a 50% chance to gain 50% mana regeneration while casting spells for 15 sec, and Stormstrike's cooldown has a 50% chance to reset each time you Dodge or Parry.", "When you Stormstrike, you have a 100% chance to gain 50% mana regeneration while casting spells for 15 sec, and Stormstrike's cooldown has a 100% chance to reset each time you Dodge or Parry." },
	{ "When you deal damage with a melee attack, you have a chance to reduce the cast time and Mana cost of your next Lightning Bolt spell by 4%. Stacks up to 5 times. Lasts 30 sec.", "When you deal damage with a melee attack, you have a chance to reduce the cast time and Mana cost of your next Lightning Bolt spell by 8%. Stacks up to 5 times. Lasts 30 sec.", "When you deal damage with a melee attack, you have a chance to reduce the cast time and Mana cost of your next Lightning Bolt spell by 12%. Stacks up to 5 times. Lasts 30 sec.", "When you deal damage with a melee attack, you have a chance to reduce the cast time and Mana cost of your next Lightning Bolt spell by 16%. Stacks up to 5 times. Lasts 30 sec.", "When you deal damage with a melee attack, you have a chance to reduce the cast time and Mana cost of your next Lightning Bolt spell by 20%. Stacks up to 5 times. Lasts 30 sec." },
	{ "Increases your attack speed by 30% for 25 sec.", cost = "Instant | 3 min cooldown" },
},
