	{ "Increases your target's armor value by 8% for 15 sec after getting a critical effect from one of your healing spells.", "Increases your target's armor value by 17% for 15 sec after getting a critical effect from one of your healing spells.", "Increases your target's armor value by 25% for 15 sec after getting a critical effect from one of your healing spells." },
	{ "Gives you a 23% chance to avoid interruption caused by damage while casting any healing spell.", "Gives you a 47% chance to avoid interruption caused by damage while casting any healing spell.", "Gives you a 70% chance to avoid interruption caused by damage while casting any healing spell." },
	{ "The caster is surrounded by 3 globes of water. When a spell, melee, or ranged attack hits the caster or when one of the caster's healing spells gets a critical result, 2% of maximum mana is restored to the caster, expending one water globe. Only one globe will activate every few seconds. Lasts 10 min.\n\nOnly one Elemental Shield can be active on the Shaman at any one time.", cost = "Instant | 15 sec cooldown" },
	{ "Increases the critical effect chance of your healing spells by 1%.", "Increases the critical effect chance of your healing spells by 2%.", "Increases the critical effect chance of your healing spells by 3%.", "Increases the critical effect chance of your healing spells by 4%.", "Increases the critical effect chance of your healing spells by 5%." },
	{ "Increases the effect of your Mana Spring Totem by 5% and increases the effect of your Healing Stream Totem by 10%.", "Increases the effect of your Mana Spring Totem by 10% and increases the effect of your Healing Stream Totem by 20%.", "Increases the effect of your Mana Spring Totem by 15% and increases the effect of your Healing Stream Totem by 30%.", "Increases the effect of your Mana Spring Totem by 20% and increases the effect of your Healing Stream Totem by 40%.", "Increases the effect of your Mana Spring Totem by 25% and increases the effect of your Healing Stream Totem by 50%." },
	{ "Summons a Mana Tide Totem with 5 health at the feet of the caster for 12 sec that restores 88 mana every 3 seconds to group members within 30 yards.", cost = "10 Mana | Instant | 5 min cooldown" },
	{ "Increases the amount healed by your Healing Wave spell by 8%.", "Increases the amount healed by your Healing Wave spell by 17%.", "Increases the amount healed by your Healing Wave spell by 25%." },
	{ "When activated, your next Nature spell with a casting time less than 10 sec. becomes an instant cast spell.", cost = "Instant | 3 min cooldown" },
	{ "Increases the effectiveness of your healing spells by 2%.", "Increases the effectiveness of your healing spells by 4%.", "Increases the effectiveness of your healing spells by 6%.", "Increases the effectiveness of your healing spells by 8%.", "Increases the effectiveness of your healing spells by 10%." },
	{ "Heals a friendly target for 485 to 533, an additional 445 over 15 sec, and increases the effectiveness of your Chain Heal casts directly on that target by 25%.", cost = "245 Mana | 40 yd range | Instant | 6 sec cooldown" },
},
[81] = {
	{ "Increases your damage with Wands by 13%.", "Increases your damage with Wands by 25%." },
	{ "Improves your chance to hit with Arcane spells by 1%.", "Improves your chance to hit with Arcane spells by 2%.", "Improves your chance to hit with Arcane spells by 3%.", "Improves your chance to hit with Arcane spells by 4%.", "Improves your chance to hit with Arcane spells by 5%." },
	{ "Gives you a 20% chance to avoid interruption caused by damage while channeling Arcane Missiles and a 14% chance while casting Arcane Blast.", "Gives you a 40% chance to avoid interruption caused by damage while channeling Arcane Missiles and a 28% chance while casting Arcane Blast.", "Gives you a 60% chance to avoid interruption caused by damage while channeling Arcane Missiles and a 42% chance while casting Arcane Blast.", "Gives you a 80% chance to avoid interruption caused by damage while channeling Arcane Missiles and a 56% chance while casting Arcane Blast.", "Gives you a 100% chance to avoid interruption caused by damage while channeling Arcane Missiles and a 70% chance while casting Arcane Blast." },
	{ "Reduces your target's resistance to all your spells by 8 and reduces the threat caused by your Arcane spells by 15%.", "Reduces your target's resistance to all your spells by 15 and reduces the threat caused by your Arcane spells by 30%." },
	{ "Increases all your resistances by 5 and causes all spells you fully resist to restore 1% of your total mana. Cannot trigger more often than 1 time per sec.", "Increases all your resistances by 10 and causes all spells you fully resist to restore 2% of your total mana. Cannot trigger more often than 1 time per sec." },
	{ "Gives you a 2% chance of entering a Clearcasting state after any damage spell hits a target. The Clearcasting state reduces the mana cost of your next damage spell by 100%.", "Gives you a 4% chance of entering a Clearcasting state after any damage spell hits a target. The Clearcasting state reduces the mana cost of your next damage spell by 100%.", "Gives you a 6% chance of entering a Clearcasting state after any damage spell hits a target. The Clearcasting state reduces the mana cost of your next damage spell by 100%.", "Gives you a 8% chance of entering a Clearcasting state after any damage spell hits a target. The Clearcasting state reduces the mana cost of your next damage spell by 100%.", "Gives you a 10% chance of entering a Clearcasting state after any damage spell hits a target. The Clearcasting state reduces the mana cost of your next damage spell by 100%." },
	{ "Increases your Armor by an amount equal to 25% of your Intellect.", "Increases your Armor by an amount equal to 50% of your Intellect." },
	{ "Increases the range of your Arcane spells by 3 yards.", "Increases the range of your Arcane spells by 6 yards." },
	{ "Increases the critical strike chance of your Arcane spells by 2%.", "Increases the critical strike chance of your Arcane spells by 4%.", "Increases the critical strike chance of your Arcane spells by 6%." },
	{ "Blasts the target with energy, dealing 57 to 65 Arcane damage. Each time you cast Arcane Blast, the damage of all your other spells is increased by 10% and the mana cost of Arcane Blast is increased by 175%. Effect stacks up to 4 times and lasts 8 sec or until any other damage spell is cast.", cost = "15% of base mana | 30 yd range | 2.5 sec cast" },
	{ "Decreases the Mana lost per point of damage taken when your Mana Shield spell is active by 17% and increases the resistances granted by your Mage Armor spell by 25%.", "Decreases the Mana lost per point of damage taken when your Mana Shield spell is active by 33% and increases the resistances granted by your Mage Armor spell by 50%." },
	{ "Your Counterspell also Silences the target for 2 sec.", "Your Counterspell also Silences the target for 4 sec." },
	{ "Allows 17% of your Mana regeneration to continue while casting.", "Allows 33% of your Mana regeneration to continue while casting.", "Allows 50% of your Mana regeneration to continue while casting." },
	{ "Gives your Arcane Blast spell a 40% chance, and your Fireball, Frostbolt, and Frostfire Bolt spells a 20% chance to reduce the channeled duration of your next Arcane Missiles spell by 50%, reduce the Mana cost by 100%, and missiles fire every 0.5 sec." },
	{ "When activated, your next Mage spell with a casting time less than 10 sec becomes an instant cast spell.", cost = "Instant | 3 min cooldown" },
	{ "Increases your Intellect by 2% and increases the critical strike damage bonus of your Arcane spells by 20%.", "Increases your Intellect by 4% and increases the critical strike damage bonus of your Arcane spells by 40%.", "Increases your Intellect by 6% and increases the critical strike damage bonus of your Arcane spells by 60%.", "Increases your Intellect by 8% and increases the critical strike damage bonus of your Arcane spells by 80%.", "Increases your Intellect by 10% and increases the critical strike damage bonus of your Arcane spells by 100%." },
	{ "Increases the damage done by your spells by 1% and your critical strike chance by 1%.", "Increases the damage done by your spells by 2% and your critical strike chance by 2%.", "Increases the damage done by your spells by 3% and your critical strike chance by 3%." },
	{ "For the next 15 sec, your spells deal 30% more damage while costing 30% more mana to cast.", cost = "Instant | 3 min cooldown" },
},
[41] = {
	{ "Reduces the cooldown of your Fire Blast spell by 1 sec. Killing a non-trivial target increases the critical strike chance of your next Fire Blast cast within 30 sec by 25%.", "Reduces the cooldown of your Fire Blast spell by 2 sec. Killing a non-trivial target increases the critical strike chance of your next Fire Blast cast within 30 sec by 50%." },
	{ "Increases the critical strike chance of your Fire Blast, Ice Lance, Arcane Blast, and Scorch spells by 2%.", "Increases the critical strike chance of your Fire Blast, Ice Lance, Arcane Blast, and Scorch spells by 4%.", "Increases the critical strike chance of your Fire Blast, Ice Lance, Arcane Blast, and Scorch spells by 6%." },
	{ "Reduces the casting time of your Fireball and Frostfire Bolt spells by 0.1 sec.", "Reduces the casting time of your Fireball and Frostfire Bolt spells by 0.2 sec.", "Reduces the casting time of your Fireball and Frostfire Bolt spells by 0.3 sec.", "Reduces the casting time of your Fireball and Frostfire Bolt spells by 0.4 sec.", "Reduces the casting time of your Fireball and Frostfire Bolt spells by 0.5 sec." },
	{ "Your critical strikes from Fire damage spells cause the target to burn for an additional 8% of your spell's damage over 4 sec.", "Your critical strikes from Fire damage spells cause the target to burn for an additional 16% of your spell's damage over 4 sec.", "Your critical strikes from Fire damage spells cause the target to burn for an additional 24% of your spell's damage over 4 sec.", "Your critical strikes from Fire damage spells cause the target to burn for an additional 32% of your spell's damage over 4 sec.", "Your critical strikes from Fire damage spells cause the target to burn for an additional 40% of your spell's damage over 4 sec." },
	{ "Increases the range of your Fire spells by 3 yards.", "Increases the range of your Fire spells by 6 yards." },
	{ "Gives your Fire spells a 3% chance to stun the target for 2 sec.", "Gives your Fire spells a 7% chance to stun the target for 2 sec.", "Gives your Fire spells a 10% chance to stun the target for 2 sec." },
	{ "Gives your Fire spells a 23% chance to not lose casting time when you take damage and reduces the threat caused by your Fire spells by 10%.", "Gives your Fire spells a 47% chance to not lose casting time when you take damage and reduces the threat caused by your Fire spells by 20%.", "Gives your Fire spells a 70% chance to not lose casting time when you take damage and reduces the threat caused by your Fire spells by 30%." },
	{ "Increases the critical strike chance of your Flamestrike spell by 5%.", "Increases the critical strike chance of your Flamestrike spell by 10%.", "Increases the critical strike chance of your Flamestrike spell by 15%." },
	{ "Hurls an immense fiery boulder that causes 101 to 131 Fire damage and an additional 44 Fire damage over 12 sec.", cost = "125 Mana | 35 yd range | 6 sec cast" },
	{ "Your Scorch spell has a 33% chance to cause your target to be vulnerable to Fire damage. This vulnerability increases all Fire damage you deal to your target by 3% and lasts 30 sec, stacking up to 5 times.", "Your Scorch spell has a 67% chance to cause your target to be vulnerable to Fire damage. This vulnerability increases all Fire damage you deal to your target by 3% and lasts 30 sec, stacking up to 5 times.", "Your Scorch spell has a 100% chance to cause your target to be vulnerable to Fire damage. This vulnerability increases all Fire damage you deal to your target by 3% and lasts 30 sec, stacking up to 5 times." },
	{ "Causes your Fire Ward to have a 10% chance to reflect Fire spells while active.", "Causes your Fire Ward to have a 20% chance to reflect Fire spells while active." },
	{ "Your non-periodic critical strikes with Fireball, Frostfire Bolt, Fire Blast, and Scorch grant Hot Streak for 20 sec. Hot Streak reduces the cast time of Pyroblast by 25%, stacking up to 3 times." },
	{ "Your Fire and Frost critical strikes will refund 10% of their base mana cost.", "Your Fire and Frost critical strikes will refund 20% of their base mana cost.", "Your Fire and Frost critical strikes will refund 30% of their base mana cost." },
	{ "Increases the critical strike chance of your Fire spells by 2%.", "Increases the critical strike chance of your Fire spells by 4%.", "Increases the critical strike chance of your Fire spells by 6%." },
	{ "A wave of flame radiates outward from the caster, damaging all enemies caught within the blast for 154 to 184 Fire damage, and Dazing them for 50% reduced movement speed for 6 sec.", cost = "215 Mana | Instant | 45 sec cooldown" },
	{ "Increases the damage done by your Fire spells by 2%.", "Increases the damage done by your Fire spells by 4%.", "Increases the damage done by your Fire spells by 6%.", "Increases the damage done by your Fire spells by 8%.", "Increases the damage done by your Fire spells by 10%." },
	{ "When activated, this spell causes each of your Fire damage spell hits to increase your critical strike chance with Fire damage spells by 10%. This effect lasts until you have caused 4 non-periodic critical strikes with Fire spells.", cost = "Instant | 3 min cooldown" },
},
[61] = {
	{ "Increases the Armor and resistance given by your Frost Armor and Ice Armor spells by 15%. In addition, gives your Frost Ward a 10% chance to reflect Frost spells and effects while active.", "Increases the Armor and resistance given by your Frost Armor and Ice Armor spells by 30%. In addition, gives your Frost Ward a 20% chance to reflect Frost spells and effects while active." },
	{ "Reduces the casting time of your Frostbolt spell by 0.1 sec.", "Reduces the casting time of your Frostbolt spell by 0.2 sec.", "Reduces the casting time of your Frostbolt spell by 0.3 sec.", "Reduces the casting time of your Frostbolt spell by 0.4 sec.", "Reduces the casting time of your Frostbolt spell by 0.5 sec." },
	{ "Improves your chance to hit with Frost and Fire spells by 1%.", "Improves your chance to hit with Frost and Fire spells by 2%.", "Improves your chance to hit with Frost and Fire spells by 3%.", "Improves your chance to hit with Frost and Fire spells by 4%.", "Improves your chance to hit with Frost and Fire spells by 5%." },
	{ "Increases the critical strike damage bonus of your Frost spells by 20%.", "Increases the critical strike damage bonus of your Frost spells by 40%.", "Increases the critical strike damage bonus of your Frost spells by 60%.", "Increases the critical strike damage bonus of your Frost spells by 80%.", "Increases the critical strike damage bonus of your Frost spells by 100%." },
	{ "Increases the duration of your Chill effects by 11% and reduces the target's speed by an additional 3%.", "Increases the duration of your Chill effects by 22% and reduces the target's speed by an additional 7%.", "Increases the duration of your Chill effects by 33% and reduces the target's speed by an additional 10%." },
	{ "Reduces the cooldown of your Frost Nova spell by 2 sec.", "Reduces the cooldown of your Frost Nova spell by 4 sec." },
	{ "Gives your Chill effects a 5% chance to Freeze the target for 5 sec.", "Gives your Chill effects a 10% chance to Freeze the target for 5 sec.", "Gives your Chill effects a 15% chance to Freeze the target for 5 sec." },
	{ "Increases the damage done by your Frost spells by 2%.", "Increases the damage done by your Frost spells by 4%.", "Increases the damage done by your Frost spells by 6%." },
	{ "Reduces the mana cost of your Frost spells by 5% and reduces the threat caused by your Frost spells by 10%.", "Reduces the mana cost of your Frost spells by 10% and reduces the threat caused by your Frost spells by 20%.", "Reduces the mana cost of your Frost spells by 15% and reduces the threat caused by your Frost spells by 30%." },
	{ "Deals 28 to 32 Frost damage to an enemy target. Deals 300% increased damage to Frozen targets.", cost = "45 Mana | 30 yd range | Instant" },
	{ "Adds a Chill effect to your Blizzard spell. This effect lowers the target's movement speed by 15% for 1.5 sec.", "Adds a Chill effect to your Blizzard spell. This effect lowers the target's movement speed by 25% for 1.5 sec.", "Adds a Chill effect to your Blizzard spell. This effect lowers the target's movement speed by 40% for 1.5 sec." },
	{ "Increases the range of your Frostbolt and Blizzard spells and the radius of your Frost Nova and Cone of Cold spells by 10%.", "Increases the range of your Frostbolt and Blizzard spells and the radius of your Frost Nova and Cone of Cold spells by 20%." },
	{ "You become encased in a block of ice, protecting you from all physical attacks and spells for 10 sec, but during that time you cannot attack, move, or cast spells.", cost = "15 Mana | Instant | 5 min cooldown" },
	{ "Increases the critical strike chance of all your spells against Frozen targets by 17%.", "Increases the critical strike chance of all your spells against Frozen targets by 33%.", "Increases the critical strike chance of all your spells against Frozen targets by 50%." },
	{ "Increases the damage dealt by your Cone of Cold spell by 12%.", "Increases the damage dealt by your Cone of Cold spell by 23%.", "Increases the damage dealt by your Cone of Cold spell by 35%." },
	{ "Finishes the remaining cooldown on all your other Frost spells.", cost = "Instant | 10 min cooldown" },
	{ "Gives your Chill effects a 15% chance to grant you the Fingers of Frost effect, which treats your next 1 spell cast as if the target were Frozen. Lasts 15 sec.", "Gives your Chill effects a 15% chance to grant you the Fingers of Frost effect, which treats your next 2 spells cast as if the target were Frozen. Lasts 15 sec." },
	{ "Gives your Frost damage spells a 20% chance to apply the Winter's Chill effect, which increases the chance your Ice Lance and Frostbolt spells will critically hit the target by 2% for 15 sec. Stacks up to 1 times.", "Gives your Frost damage spells a 40% chance to apply the Winter's Chill effect, which increases the chance your Ice Lance and Frostbolt spells will critically hit the target by 2% for 15 sec. Stacks up to 2 times.", "Gives your Frost damage spells a 60% chance to apply the Winter's Chill effect, which increases the chance your Ice Lance and Frostbolt spells will critically hit the target by 2% for 15 sec. Stacks up to 3 times.", "Gives your Frost damage spells a 80% chance to apply the Winter's Chill effect, which increases the chance your Ice Lance and Frostbolt spells will critically hit the target by 2% for 15 sec. Stacks up to 4 times.", "Gives your Frost damage spells a 100% chance to apply the Winter's Chill effect, which increases the chance your Ice Lance and Frostbolt spells will critically hit the target by 2% for 15 sec. Stacks up to 5 times." },
	{ "Instantly shields you, absorbing 447 damage. Lasts 1 min. While the shield holds, your spellcasts will not be interrupted or delayed from taking damage.", cost = "305 Mana | Instant | 30 sec cooldown" },
},
[302] = {
	{ "Increases the amount of Mana awarded by your Life Tap spell by 10%.", "Increases the amount of Mana awarded by your Life Tap spell by 20%." },
	{ "Improves your chance to hit by 1% and reduces all threat you generate by 4%.", "Improves your chance to hit by 2% and reduces all threat you generate by 8%.", "Improves your chance to hit by 3% and reduces all threat you generate by 12%.", "Improves your chance to hit by 4% and reduces all threat you generate by 16%.", "Improves your chance to hit by 5% and reduces all threat you generate by 20%." },
	{ "Reduces the casting time of your Corruption spell by 0.4 sec and increases the damage it deals by 2%.", "Reduces the casting time of your Corruption spell by 0.8 sec and increases the damage it deals by 4%.", "Reduces the casting time of your Corruption spell by 1.2 sec and increases the damage it deals by 6%.", "Reduces the casting time of your Corruption spell by 1.6 sec and increases the damage it deals by 8%.", "Reduces the casting time of your Corruption spell by 2 sec and increases the damage it deals by 10%." },
	{ "Increases all periodic damage done by your Warlock spells by 1%.", "Increases all periodic damage done by your Warlock spells by 2%.", "Increases all periodic damage done by your Warlock spells by 3%.", "Increases all periodic damage done by your Warlock spells by 4%.", "Increases all periodic damage done by your Warlock spells by 5%." },
	{ "You gain Soul Harvest for 10 sec if a victim is killed while afflicted with your Drain Soul. Soul Harvest allows your Mana to regenerate at 50% of normal speed while you are casting spells, and grants a 50% increase to your Mana regeneration.", "You gain Soul Harvest for 10 sec if a victim is killed while afflicted with your Drain Soul. Soul Harvest allows your Mana to regenerate at 100% of normal speed while you are casting spells, and grants a 100% increase to your Mana regeneration." },
	{ "Increases health drained or damage done by your Drain Life, Drain Soul, and Wrack spells by 7%.", "Increases health drained or damage done by your Drain Life, Drain Soul, and Wrack spells by 13%.", "Increases health drained or damage done by your Drain Life, Drain Soul, and Wrack spells by 20%." },
	{ "Increases the damage done by your Bane of Agony by 5%.", "Increases the damage done by your Bane of Agony by 10%." },
	{ "Gives you a 23% chance to avoid interruption caused by damage while channeling or casting your Drain Life, Drain Mana, Drain Soul, or Wrack spells.", "Gives you a 47% chance to avoid interruption caused by damage while channeling or casting your Drain Life, Drain Mana, Drain Soul, or Wrack spells.", "Gives you a 70% chance to avoid interruption caused by damage while channeling or casting your Drain Life, Drain Mana, Drain Soul, or Wrack spells." },
	{ "Increases the effect of your next Curse of Weakness or Bane of Agony by 50%, or your next Curse of Exhaustion by 20%. Lasts 30 sec.", cost = "Instant | 3 min cooldown" },
	{ "Increases the critical strike damage bonus of your Corruption, Bane of Agony, Bane of Doom, Drain Soul, Drain Life, Siphon Life, and Wrack spells by 33%.", "Increases the critical strike damage bonus of your Corruption, Bane of Agony, Bane of Doom, Drain Soul, Drain Life, Siphon Life, and Wrack spells by 67%.", "Increases the critical strike damage bonus of your Corruption, Bane of Agony, Bane of Doom, Drain Soul, Drain Life, Siphon Life, and Wrack spells by 100%." },
	{ "Increases the critical effect chance of your Shadow spells by 1%.", "Increases the critical effect chance of your Shadow spells by 2%.", "Increases the critical effect chance of your Shadow spells by 3%.", "Increases the critical effect chance of your Shadow spells by 4%.", "Increases the critical effect chance of your Shadow spells by 5%." },
	{ "Gives your Corruption, Drain Soul, Drain Life, and Wrack spells a 2% chance to cause you to enter a Shadow Trance after damaging the opponent. The Shadow Trance reduces the casting time of your next Shadow Bolt spell by 100%.", "Gives your Corruption, Drain Soul, Drain Life, and Wrack spells a 4% chance to cause you to enter a Shadow Trance after damaging the opponent. The Shadow Trance reduces the casting time of your next Shadow Bolt spell by 100%." },
	{ "Reduces the target's movement speed by 30% for 12 sec. Only one Curse per Warlock can be active on any one target.", cost = "8% of base mana | 30 yd range | Instant" },
	{ "Transfers 11 health from the target to the caster every 3 sec. Lasts 30 sec.", cost = "150 Mana | 30 yd range | Instant" },
	{ "Increases the damage done or health drained by your Drain Life, Drain Soul, and Wrack spells by 4% per each of your other Affliction effects active on the target, up to a maximum increase of 12%.", "Increases the damage done or health drained by your Drain Life, Drain Soul, and Wrack spells by 8% per each of your other Affliction effects active on the target, up to a maximum increase of 24%.", "Increases the damage done or health drained by your Drain Life, Drain Soul, and Wrack spells by 12% per each of your other Affliction effects active on the target, up to a maximum increase of 36%." },
	{ "Increases the damage dealt or life drained by your Shadow spells by 1%.", "Increases the damage dealt or life drained by your Shadow spells by 2%.", "Increases the damage dealt or life drained by your Shadow spells by 3%.", "Increases the damage dealt or life drained by your Shadow spells by 4%.", "Increases the damage dealt or life drained by your Shadow spells by 5%." },
	{ "Tears the target apart from within, dealing 36 Shadow damage every 1 sec and increasing the damage they take from your other Shadow damage over time effects by 10%. Lasts 6 sec.", cost = "200 Mana | 30 yd range | Channeled" },
},
[303] = {
	{ "Increases the amount of health transferred by your Health Funnel spell by 20%, reduces its health cost by 15%, and reduces all threat your Health Funnel generates by 50%. Allows Health Funnel to be used regardless of your demon's health.", "Increases the amount of health transferred by your Health Funnel spell by 40%, reduces its health cost by 30%, and reduces all threat your Health Funnel generates by 100%. Allows Health Funnel to be used regardless of your demon's health." },
	{ "Increases the damage of your Imp's Firebolt spell by 10% and the effect of its Fire Shield spell by 10%.", "Increases the damage of your Imp's Firebolt spell by 20% and the effect of its Fire Shield spell by 20%.", "Increases the damage of your Imp's Firebolt spell by 30% and the effect of its Fire Shield spell by 30%." },
	{ "Increases your total Stamina by 3%.", "Increases your total Stamina by 6%.", "Increases your total Stamina by 9%.", "Increases your total Stamina by 12%.", "Increases your total Stamina by 15%." },
	{ "Increases all damage done by your Imp, Voidwalker, Succubus, Incubus, and Felhunter pets by 2%.", "Increases all damage done by your Imp, Voidwalker, Succubus, Incubus, and Felhunter pets by 4%.", "Increases all damage done by your Imp, Voidwalker, Succubus, Incubus, and Felhunter pets by 6%.", "Increases all damage done by your Imp, Voidwalker, Succubus, Incubus, and Felhunter pets by 8%.", "Increases all damage done by your Imp, Voidwalker, Succubus, Incubus, and Felhunter pets by 10%." },
	{ "Increases the effectiveness of your Demon Skin and Demon Armor spells by 15%.", "Increases the effectiveness of your Demon Skin and Demon Armor spells by 30%." },
	{ "Increases the effectiveness of your Voidwalker's Torment, Consume Shadows, Sacrifice, and Suffering spells by 10%.", "Increases the effectiveness of your Voidwalker's Torment, Consume Shadows, Sacrifice, and Suffering spells by 20%.", "Increases the effectiveness of your Voidwalker's Torment, Consume Shadows, Sacrifice, and Suffering spells by 30%." },
	{ "Increases the maximum health and Mana of your Imp, Voidwalker, Succubus, Incubus, and Felhunter by 5%, and increases your maximum Mana by 5%.", "Increases the maximum health and Mana of your Imp, Voidwalker, Succubus, Incubus, and Felhunter by 10%, and increases your maximum Mana by 10%.", "Increases the maximum health and Mana of your Imp, Voidwalker, Succubus, Incubus, and Felhunter by 15%, and increases your maximum Mana by 15%." },
	{ "You heal your pet for 8% of all spell damage you deal. When you gain Mana from Life Tap, your summoned demon gains 50% of the Mana you gain.", "You heal your pet for 15% of all spell damage you deal. When you gain Mana from Life Tap, your summoned demon gains 100% of the Mana you gain." },
	{ "Increases the effect of your Succubus' and Incubus' Lash of Pain and Soothing Kiss spells by 10%, and increases the duration of your Succubus' and Incubus' Seduction and Lesser Invisibility spells by 10%.", "Increases the effect of your Succubus' and Incubus' Lash of Pain and Soothing Kiss spells by 20%, and increases the duration of your Succubus' and Incubus' Seduction and Lesser Invisibility spells by 20%.", "Increases the effect of your Succubus' and Incubus' Lash of Pain and Soothing Kiss spells by 30%, and increases the duration of your Succubus' and Incubus' Seduction and Lesser Invisibility spells by 30%." },
	{ "When activated, sacrifices your summoned Demon to enhance the opposing aspect of your power, granting you an effect that lasts 2 hrs. The effect is canceled if any Demon is summoned.\n\nImp: Increases your Shadow damage by 15%.\n\nVoidwalker: Restores 2% of your total Mana every 4 sec.\n\nSuccubus/Incubus: Increases your Fire damage by 15%.\n\nFelhunter: Restores 3% of your total Health every 4 sec.", cost = "100 yd range | Instant" },
	{ "Reduces the casting time of your Imp, Voidwalker, Succubus, Incubus, and Felhunter Summoning spells by 2 sec and the Mana cost by 20%.", "Reduces the casting time of your Imp, Voidwalker, Succubus, Incubus, and Felhunter Summoning spells by 4 sec and the Mana cost by 40%." },
	{ "Reduces the cooldown of your Soul Fire spell by 45%. When you cast Shadow Bolt or Searing Pain on an enemy below 35% health, they deal 3% increased damage, and for the next 10 sec your Soul Fire spell has its cast time reduced by 20% and costs no Soul Shards.", "Reduces the cooldown of your Soul Fire spell by 90%. When you cast Shadow Bolt or Searing Pain on an enemy below 35% health, they deal 6% increased damage, and for the next 10 sec your Soul Fire spell has its cast time reduced by 40% and costs no Soul Shards." },
	{ "Your next Imp, Voidwalker, Succubus, Incubus, or Felhunter Summon spell has its casting time reduced by 5.5 sec and its Mana cost reduced by 50%.", cost = "Instant | 5 min cooldown" },
	{ "Your Searing Pain generates 17% less threat and brands the target for 10 sec. Your pet's next 2 attacks against the target generate high threat and deal 65 to 68 Fire or Shadow damage based on the pet.", "Your Searing Pain generates 33% less threat and brands the target for 10 sec. Your pet's next 4 attacks against the target generate high threat and deal 65 to 68 Fire or Shadow damage based on the pet.", "Your Searing Pain generates 50% less threat and brands the target for 10 sec. Your pet's next 6 attacks against the target generate high threat and deal 65 to 68 Fire or Shadow damage based on the pet." },
	{ "Increases the Attack Power reduction of your Felhunter's Tainted Blood, the healing of its Devour Magic, and the detection level of its Paranoia by 10%, and reduces the cooldown of its Spell Lock by 2 sec.", "Increases the Attack Power reduction of your Felhunter's Tainted Blood, the healing of its Devour Magic, and the detection level of its Paranoia by 20%, and reduces the cooldown of its Spell Lock by 4 sec.", "Increases the Attack Power reduction of your Felhunter's Tainted Blood, the healing of its Devour Magic, and the detection level of its Paranoia by 30%, and reduces the cooldown of its Spell Lock by 6 sec." },
	{ "When active, 30% of all damage taken by the caster is taken by your Imp, Voidwalker, Succubus, Incubus, or Felhunter Demon instead. In addition, both the Demon and the master will inflict 3% more damage. Lasts as long as the Demon is active.", cost = "20% of base mana | 100 yd range | Instant" },
	{ "Increases your spell damage and your Demon pet's spell damage by up to 33% of your level while you have a summoned Demon pet active.", "Increases your spell damage and your Demon pet's spell damage by up to 67% of your level while you have a summoned Demon pet active.", "Increases your spell damage and your Demon pet's spell damage by up to 100% of your level while you have a summoned Demon pet active." },
	{ "Grants both the Warlock and the summoned demon an effect as long as that demon is active.\n\nImp - Increases Fire damage done by 2%.\n\nVoidwalker - Reduces Physical damage taken by 2%.\n\nSuccubus/Incubus - Increases Shadow damage done by 2%.\n\nFelhunter - Reduces Magic damage taken by 2%.", "Grants both the Warlock and the summoned demon an effect as long as that demon is active.\n\nImp - Increases Fire damage done by 4%.\n\nVoidwalker - Reduces Physical damage taken by 4%.\n\nSuccubus/Incubus - Increases Shadow damage done by 4%.\n\nFelhunter - Reduces Magic damage taken by 4%.", "Grants both the Warlock and the summoned demon an effect as long as that demon is active.\n\nImp - Increases Fire damage done by 6%.\n\nVoidwalker - Reduces Physical damage taken by 6%.\n\nSuccubus/Incubus - Increases Shadow damage done by 6%.\n\nFelhunter - Reduces Magic damage taken by 6%.", "Grants both the Warlock and the summoned demon an effect as long as that demon is active.\n\nImp - Increases Fire damage done by 8%.\n\nVoidwalker - Reduces Physical damage taken by 8%.\n\nSuccubus/Incubus - Increases Shadow damage done by 8%.\n\nFelhunter - Reduces Magic damage taken by 8%.", "Grants both the Warlock and the summoned demon an effect as long as that demon is active.\n\nImp - Increases Fire damage done by 10%.\n\nVoidwalker - Reduces Physical damage taken by 10%.\n\nSuccubus/Incubus - Increases Shadow damage done by 10%.\n\nFelhunter - Reduces Magic damage taken by 10%." },
	{ "Your Demonic Sacrifice effect is no longer cancelled by summoning a different Demon pet. Resummoning the sacrificed pet will still cancel the effect." },
},
[301] = {
	{ "Increases the range of your damaging spells by 10%.", "Increases the range of your damaging spells by 20%." },
	{ "Your Shadow Bolt critical strikes increase Shadow damage taken by the target from your attacks by 4% for 12 sec.", "Your Shadow Bolt critical strikes increase Shadow damage taken by the target from your attacks by 8% for 12 sec.", "Your Shadow Bolt critical strikes increase Shadow damage taken by the target from your attacks by 12% for 12 sec.", "Your Shadow Bolt critical strikes increase Shadow damage taken by the target from your attacks by 16% for 12 sec.", "Your Shadow Bolt critical strikes increase Shadow damage taken by the target from your attacks by 20% for 12 sec." },
	{ "Reduces the casting time of your Shadow Bolt, Immolate, and Incinerate spells by 0.1 sec and your Soul Fire spell by 0.4 sec.", "Reduces the casting time of your Shadow Bolt, Immolate, and Incinerate spells by 0.2 sec and your Soul Fire spell by 0.8 sec.", "Reduces the casting time of your Shadow Bolt, Immolate, and Incinerate spells by 0.3 sec and your Soul Fire spell by 1.2 sec.", "Reduces the casting time of your Shadow Bolt, Immolate, and Incinerate spells by 0.4 sec and your Soul Fire spell by 1.6 sec.", "Reduces the casting time of your Shadow Bolt, Immolate, and Incinerate spells by 0.5 sec and your Soul Fire spell by 2 sec." },
	{ "Reduces all damage taken by 2%.", "Reduces all damage taken by 4%.", "Reduces all damage taken by 6%.", "Reduces all damage taken by 8%.", "Reduces all damage taken by 10%." },
	{ "Reduces the Mana cost of your Destruction spells by 3%.", "Reduces the Mana cost of your Destruction spells by 6%.", "Reduces the Mana cost of your Destruction spells by 10%." },
	{ "Increases the initial damage of your Immolate spell by 10% and your Conflagrate spell has a 20% chance to Daze the target, reducing the target's movement speed by 50% for 5 sec.", "Increases the initial damage of your Immolate spell by 20% and your Conflagrate spell has a 40% chance to Daze the target, reducing the target's movement speed by 50% for 5 sec.", "Increases the initial damage of your Immolate spell by 30% and your Conflagrate spell has a 60% chance to Daze the target, reducing the target's movement speed by 50% for 5 sec.", "Increases the initial damage of your Immolate spell by 40% and your Conflagrate spell has a 80% chance to Daze the target, reducing the target's movement speed by 50% for 5 sec.", "Increases the initial damage of your Immolate spell by 50% and your Conflagrate spell has a 100% chance to Daze the target, reducing the target's movement speed by 50% for 5 sec." },
	{ "Increases the critical strike damage bonus of your Destruction spells by 20%.", "Increases the critical strike damage bonus of your Destruction spells by 40%.", "Increases the critical strike damage bonus of your Destruction spells by 60%.", "Increases the critical strike damage bonus of your Destruction spells by 80%.", "Increases the critical strike damage bonus of your Destruction spells by 100%." },
	{ "Instantly blasts the target for 65 to 73 Shadow damage. If a non-trivial target dies within 8 sec of being hit with Shadowburn, the caster gains a Soul Shard.", cost = "105 Mana | 30 yd range | Instant | 15 sec cooldown | Reagents: Soul Shard" },
	{ "Gives you a 23% chance to resist interruption caused by damage while casting or channeling any Destruction spell.", "Gives you a 47% chance to resist interruption caused by damage while casting or channeling any Destruction spell.", "Gives you a 70% chance to resist interruption caused by damage while casting or channeling any Destruction spell." },
	{ "Increases the critical strike chance of your Searing Pain spell by 3% and the damage done by all your Destruction spells by 3%.", "Increases the critical strike chance of your Searing Pain spell by 7% and the damage done by all your Destruction spells by 7%.", "Increases the critical strike chance of your Searing Pain spell by 10% and the damage done by all your Destruction spells by 10%." },
	{ "Ignites a target that is already afflicted by your Immolate spell, dealing 88 to 110 Fire damage and consuming your Immolate effect.", cost = "100 Mana | 30 yd range | Instant | 10 sec cooldown" },
	{ "Gives your Soul Fire spell a 13% chance to Stun the target for 3 sec, and your Rain of Fire and Hellfire spells a 13% chance over their duration to Stun targets they damage for 3 sec.", "Gives your Soul Fire spell a 26% chance to Stun the target for 3 sec, and your Rain of Fire and Hellfire spells a 26% chance over their duration to Stun targets they damage for 3 sec." },
	{ "Afflicts the target for 5 min, causing 15% of all damage done by the Warlock to other targets to also be dealt to the cursed target. Bane of Havoc is limited to 1 target, and only one Bane per Warlock can be active on any one target.", cost = "5% of base mana | 30 yd range | Instant" },
	{ "Increases the critical strike chance of your Conflagrate spell by 8%.", "Increases the critical strike chance of your Conflagrate spell by 17%.", "Increases the critical strike chance of your Conflagrate spell by 25%." },
	{ "Hitting an enemy with Conflagrate increases all Shadow damage you deal by 2% for 20 sec, and hitting an enemy with Shadowburn increases all Fire damage you deal by 2% for 20 sec. In addition, Conflagrate has a 20% chance not to consume Immolate, and Shadowburn has a 20% chance to instantly refund a Soul Shard.", "Hitting an enemy with Conflagrate increases all Shadow damage you deal by 4% for 20 sec, and hitting an enemy with Shadowburn increases all Fire damage you deal by 4% for 20 sec. In addition, Conflagrate has a 40% chance not to consume Immolate, and Shadowburn has a 40% chance to instantly refund a Soul Shard.", "Hitting an enemy with Conflagrate increases all Shadow damage you deal by 6% for 20 sec, and hitting an enemy with Shadowburn increases all Fire damage you deal by 6% for 20 sec. In addition, Conflagrate has a 60% chance not to consume Immolate, and Shadowburn has a 60% chance to instantly refund a Soul Shard.", "Hitting an enemy with Conflagrate increases all Shadow damage you deal by 8% for 20 sec, and hitting an enemy with Shadowburn increases all Fire damage you deal by 8% for 20 sec. In addition, Conflagrate has a 80% chance not to consume Immolate, and Shadowburn has a 80% chance to instantly refund a Soul Shard.", "Hitting an enemy with Conflagrate increases all Shadow damage you deal by 10% for 20 sec, and hitting an enemy with Shadowburn increases all Fire damage you deal by 10% for 20 sec. In addition, Conflagrate has a 100% chance not to consume Immolate, and Shadowburn has a 100% chance to instantly refund a Soul Shard." },
	{ "Deals 99 to 113 Fire damage to your target and an additional 25% damage if the target is afflicted by Immolate.", cost = "205 Mana | 30 yd range | 2.5 sec cast" },
},
[283] = {
	{ "Reduces the cast time of your Wrath spell by 0.1 sec and its Mana cost by 10%.", "Reduces the cast time of your Wrath spell by 0.2 sec and its Mana cost by 20%.", "Reduces the cast time of your Wrath spell by 0.3 sec and its Mana cost by 30%.", "Reduces the cast time of your Wrath spell by 0.4 sec and its Mana cost by 40%.", "Reduces the cast time of your Wrath spell by 0.5 sec and its Mana cost by 50%." },
	{ "Increases the periodic damage and healing done by your spells and abilities by 1%.", "Increases the periodic damage and healing done by your spells and abilities by 2%.", "Increases the periodic damage and healing done by your spells and abilities by 3%.", "Increases the periodic damage and healing done by your spells and abilities by 4%.", "Increases the periodic damage and healing done by your spells and abilities by 5%." },
	{ "Reduces the Mana cost of your damaging spells by 8%.", "Reduces the Mana cost of your damaging spells by 17%.", "Reduces the Mana cost of your damaging spells by 25%." },
	{ "Increases the damage and critical strike chance of your Moonfire spell by 5%.", "Increases the damage and critical strike chance of your Moonfire spell by 10%." },
	{ "Increases your critical strike chance with spells and melee attacks by 2%.", "Increases your critical strike chance with spells and melee attacks by 4%." },
	{ "Increases the range of your offensive Balance spells by 10% and improves your chance to hit by 2%.", "Increases the range of your offensive Balance spells by 20% and improves your chance to hit by 4%." },
	{ "Increases the damage done by your Entangling Roots spell by 25%, and its victims can take up to 25% more damage without interrupting the effect.", "Increases the damage done by your Entangling Roots spell by 50%, and its victims can take up to 50% more damage without interrupting the effect.", "Increases the damage done by your Entangling Roots spell by 75%, and its victims can take up to 75% more damage without interrupting the effect." },
	{ "Increases the duration of your Moonfire and Rejuvenation spells by 3 sec, your Regrowth spell by 6 sec, and your Insect Swarm spell by 2 sec." },
	{ "The enemy target is swarmed by insects, decreasing their chance to hit with attacks by 2% and causing 48 Nature damage over 12 sec.", cost = "45 Mana | 30 yd range | Instant" },
	{ "Increases the critical strike damage bonus of your Arcane and Nature spells by 20%.", "Increases the critical strike damage bonus of your Arcane and Nature spells by 40%.", "Increases the critical strike damage bonus of your Arcane and Nature spells by 60%.", "Increases the critical strike damage bonus of your Arcane and Nature spells by 80%.", "Increases the critical strike damage bonus of your Arcane and Nature spells by 100%." },
	{ "Reduces the cast time of Starfire by 0.1 sec and Starfire has a 3% chance to stun its target for 3 sec.", "Reduces the cast time of Starfire by 0.2 sec and Starfire has a 6% chance to stun its target for 3 sec.", "Reduces the cast time of Starfire by 0.3 sec and Starfire has a 9% chance to stun its target for 3 sec.", "Reduces the cast time of Starfire by 0.4 sec and Starfire has a 12% chance to stun its target for 3 sec.", "Reduces the cast time of Starfire by 0.5 sec and Starfire has a 15% chance to stun its target for 3 sec." },
	{ "Increases the maximum number of targets you may have affected by Entangling Roots by 1.", "Increases the maximum number of targets you may have affected by Entangling Roots by 2." },
	{ "All non-periodic spell criticals grace you with a blessing of nature, increasing your spellcasting speed and reducing your global cooldown by 10% for 3 sec." },
	{ "Your Wrath spell reduces the cast time of your next 2 Starfire spells by 0.17 sec. Stores up to 4 charges. Lasts 15 sec.", "Your Wrath spell reduces the cast time of your next 2 Starfire spells by 0.33 sec. Stores up to 4 charges. Lasts 15 sec.", "Your Wrath spell reduces the cast time of your next 2 Starfire spells by 0.50 sec. Stores up to 4 charges. Lasts 15 sec." },
	{ "Increases the damage done by your Arcane and Nature spells by 2%.", "Increases the damage done by your Arcane and Nature spells by 4%.", "Increases the damage done by your Arcane and Nature spells by 6%.", "Increases the damage done by your Arcane and Nature spells by 8%.", "Increases the damage done by your Arcane and Nature spells by 10%." },
	{ "Transforms the Druid into Moonkin Form. While in this form, the armor contribution from items is increased by 360%, Omen of Clarity gains 100% increased chance to trigger, and all party members within 45 yards have their critical strike chance increased by 3%, exclusive with Leader of the Pack. The Moonkin cannot cast healing spells while shapeshifted.\n\nThe act of shapeshifting frees the caster of Polymorph and Movement Impairing effects.", cost = "35% of base mana | Instant" },
},
[281] = {
	{ "Reduces the cost of your Maul, Primal Bite, Swipe, Claw, and Rake abilities by 1 Rage or Energy.", "Reduces the cost of your Maul, Primal Bite, Swipe, Claw, and Rake abilities by 2 Rage or Energy.", "Reduces the cost of your Maul, Primal Bite, Swipe, Claw, and Rake abilities by 3 Rage or Energy.", "Reduces the cost of your Maul, Primal Bite, Swipe, Claw, and Rake abilities by 4 Rage or Energy.", "Reduces the cost of your Maul, Primal Bite, Swipe, Claw, and Rake abilities by 5 Rage or Energy." },
	{ "Increases your Intellect by 2%. In addition, while in Bear Form or Dire Bear Form your Stamina is increased by 4% and while in Cat Form your Strength is increased by 2%.", "Increases your Intellect by 4%. In addition, while in Bear Form or Dire Bear Form your Stamina is increased by 8% and while in Cat Form your Strength is increased by 4%.", "Increases your Intellect by 6%. In addition, while in Bear Form or Dire Bear Form your Stamina is increased by 12% and while in Cat Form your Strength is increased by 6%.", "Increases your Intellect by 8%. In addition, while in Bear Form or Dire Bear Form your Stamina is increased by 16% and while in Cat Form your Strength is increased by 8%.", "Increases your Intellect by 10%. In addition, while in Bear Form or Dire Bear Form your Stamina is increased by 20% and while in Cat Form your Strength is increased by 10%." },
	{ "Increases your movement speed while in Cat Form by 15%, and increases your chance to Dodge by 2%.", "Increases your movement speed while in Cat Form by 30%, and increases your chance to Dodge by 4%." },
	{ "Increases damage done by your Swipe ability by 10% and reduces the chance enemies have to detect you while Prowling as if you were 1 level higher.", "Increases damage done by your Swipe ability by 20% and reduces the chance enemies have to detect you while Prowling as if you were 2 levels higher.", "Increases damage done by your Swipe ability by 30% and reduces the chance enemies have to detect you while Prowling as if you were 3 levels higher." },
	{ "Increases the stun duration of your Bash and Pounce abilities by 0.5 sec and reduces the cooldown of Bash by 15 sec.", "Increases the stun duration of your Bash and Pounce abilities by 1 sec and reduces the cooldown of Bash by 30 sec." },
	{ "While in Bear Form, Cat Form, Dire Bear Form, or Moonkin Form, you gain 1 additional base Armor per level and another 0.67 base Armor for each point of defense skill beyond five times your level. This amount can be further increased by multipliers from those forms.", "While in Bear Form, Cat Form, Dire Bear Form, or Moonkin Form, you gain 2 additional base Armor per level and another 1.33 base Armor for each point of defense skill beyond five times your level. This amount can be further increased by multipliers from those forms.", "While in Bear Form, Cat Form, Dire Bear Form, or Moonkin Form, you gain 3 additional base Armor per level and another 2.00 base Armor for each point of defense skill beyond five times your level. This amount can be further increased by multipliers from those forms." },
	{ "Increases the damage caused by your Claw, Rake, Shred, Maul, and Swipe abilities by 5%.", "Increases the damage caused by your Claw, Rake, Shred, Maul, and Swipe abilities by 10%." },
	{ "Charge an enemy, immobilizing them and interrupting any spell they are casting for 4 sec.\n\nLeap behind an enemy.", cost = "5 Rage | 8-25 yd range | Instant | 15 sec cooldown | Requires Cat Form, Bear Form, Dire Bear Form" },
	{ "Increases your critical strike chance while in Bear Form, Dire Bear Form, or Cat Form by 3%.", "Increases your critical strike chance while in Bear Form, Dire Bear Form, or Cat Form by 6%." },
	{ "Reduces the Energy cost of your Shred ability by 6 and reduces the Rage cost of your Lacerate ability by 1.", "Reduces the Energy cost of your Shred ability by 12 and reduces the Rage cost of your Lacerate ability by 2.", "Reduces the Energy cost of your Shred ability by 18 and reduces the Rage cost of your Lacerate ability by 3." },
	{ "Bite the target for 100% normal damage plus 26.", cost = "20 Rage | Melee Range | Instant | 6 sec cooldown | Requires Bear Form, Dire Bear Form" },
	{ "Increases your melee Attack Power in Cat Form, Bear Form, and Dire Bear Form by 50% of your level.", "Increases your melee Attack Power in Cat Form, Bear Form, and Dire Bear Form by 100% of your level.", "Increases your melee Attack Power in Cat Form, Bear Form, and Dire Bear Form by 150% of your level." },
	{ "Gives you a 50% chance to gain an additional 5 Rage any time you get a critical strike while in Bear Form or Dire Bear Form. In addition, your non-periodic critical strikes from Cat Form abilities that generate Combo Points have a 50% chance to add an additional Combo Point.", "Gives you a 100% chance to gain an additional 5 Rage any time you get a critical strike while in Bear Form or Dire Bear Form. In addition, your non-periodic critical strikes from Cat Form abilities that generate Combo Points have a 100% chance to add an additional Combo Point." },
	{ "Increases the critical strike damage bonus of your melee abilities by 10%.", "Increases the critical strike damage bonus of your melee abilities by 20%." },
	{ "While in Cat Form, Bear Form, or Dire Bear Form, the Leader of the Pack increases the critical strike chance of all party members within 45 yards by 3%, exclusive with Moonkin Aura." },
	{ "Tiger's Fury now instantly grants you 20 Energy.", "Tiger's Fury now instantly grants you 40 Energy.", "Tiger's Fury now instantly grants you 60 Energy." },
	{ "Increases your dodge chance by 1%, and gives you a 20% chance to gain 5 Rage each time you dodge.", "Increases your dodge chance by 2%, and gives you a 40% chance to gain 5 Rage each time you dodge.", "Increases your dodge chance by 3%, and gives you a 60% chance to gain 5 Rage each time you dodge.", "Increases your dodge chance by 4%, and gives you a 80% chance to gain 5 Rage each time you dodge.", "Increases your dodge chance by 5%, and gives you a 100% chance to gain 5 Rage each time you dodge." },
	{ "Increases damage done by your melee abilities on Bleeding targets by 2%.", "Increases damage done by your melee abilities on Bleeding targets by 4%.", "Increases damage done by your melee abilities on Bleeding targets by 6%.", "Increases damage done by your melee abilities on Bleeding targets by 8%.", "Increases damage done by your melee abilities on Bleeding targets by 10%." },
	{ "Causes your Primal Bite ability to strike up to 3 targets, removes its cooldown, and increases the critical strike chance of your Combo Point-generating abilities by 100%. Clears and grants immunity to Fear effects for the duration. Lasts 15 sec.", cost = "Instant | 3 min cooldown" },
},
[282] = {
	{ "Gives you a 14% chance to avoid interruption caused by damage while casting Arcane and Nature spells.", "Gives you a 28% chance to avoid interruption caused by damage while casting Arcane and Nature spells.", "Gives you a 42% chance to avoid interruption caused by damage while casting Arcane and Nature spells.", "Gives you a 56% chance to avoid interruption caused by damage while casting Arcane and Nature spells.", "Gives you a 70% chance to avoid interruption caused by damage while casting Arcane and Nature spells." },
	{ "Gives you a 20% chance to gain 10 Rage when you shapeshift into Bear Form or Dire Bear Form. When you shift into Cat Form, you will regain 20% of the Energy you had when you were last in Cat Form, plus 2 Energy for each second you spent not in Bear Form, Cat Form, or Dire Bear Form, up to a maximum of 20 Energy.", "Gives you a 40% chance to gain 10 Rage when you shapeshift into Bear Form or Dire Bear Form. When you shift into Cat Form, you will regain 40% of the Energy you had when you were last in Cat Form, plus 4 Energy for each second you spent not in Bear Form, Cat Form, or Dire Bear Form, up to a maximum of 40 Energy.", "Gives you a 60% chance to gain 10 Rage when you shapeshift into Bear Form or Dire Bear Form. When you shift into Cat Form, you will regain 60% of the Energy you had when you were last in Cat Form, plus 6 Energy for each second you spent not in Bear Form, Cat Form, or Dire Bear Form, up to a maximum of 60 Energy.", "Gives you a 80% chance to gain 10 Rage when you shapeshift into Bear Form or Dire Bear Form. When you shift into Cat Form, you will regain 80% of the Energy you had when you were last in Cat Form, plus 8 Energy for each second you spent not in Bear Form, Cat Form, or Dire Bear Form, up to a maximum of 80 Energy.", "Gives you a 100% chance to gain 10 Rage when you shapeshift into Bear Form or Dire Bear Form. When you shift into Cat Form, you will regain 100% of the Energy you had when you were last in Cat Form, plus 10 Energy for each second you spent not in Bear Form, Cat Form, or Dire Bear Form, up to a maximum of 100 Energy." },
	{ "Reduces the cast time of your Healing Touch spell by 0.1 sec and increases all damage you deal by 1%.", "Reduces the cast time of your Healing Touch spell by 0.2 sec and increases all damage you deal by 2%.", "Reduces the cast time of your Healing Touch spell by 0.3 sec and increases all damage you deal by 3%.", "Reduces the cast time of your Healing Touch spell by 0.4 sec and increases all damage you deal by 4%.", "Reduces the cast time of your Healing Touch spell by 0.5 sec and increases all damage you deal by 5%." },
	{ "Reduces the threat generated by your Nature and Arcane spells by 10%.", "Reduces the threat generated by your Nature and Arcane spells by 20%.", "Reduces the threat generated by your Nature and Arcane spells by 30%." },
	{ "Reduces the mana cost of all shapeshifting by 10%.", "Reduces the mana cost of all shapeshifting by 20%.", "Reduces the mana cost of all shapeshifting by 30%." },
	{ "Allows 17% of your Mana regeneration to continue while casting.", "Allows 33% of your Mana regeneration to continue while casting.", "Allows 50% of your Mana regeneration to continue while casting." },
	{ "Increases the effect of all your healing spells by 2%.", "Increases the effect of all your healing spells by 4%.", "Increases the effect of all your healing spells by 6%.", "Increases the effect of all your healing spells by 8%.", "Increases the effect of all your healing spells by 10%." },
	{ "Reduces the global cooldown by 0.5 seconds on your Rejuvenation, Swiftmend, and Wild Growth spells." },
	{ "Reduces the mana cost of your Healing Touch and Tranquility spells by 2%.", "Reduces the mana cost of your Healing Touch and Tranquility spells by 4%.", "Reduces the mana cost of your Healing Touch and Tranquility spells by 6%.", "Reduces the mana cost of your Healing Touch and Tranquility spells by 8%.", "Reduces the mana cost of your Healing Touch and Tranquility spells by 10%." },
	{ "Increases the effect of your Rejuvenation spell by 5%.", "Increases the effect of your Rejuvenation spell by 10%.", "Increases the effect of your Rejuvenation spell by 15%." },
	{ "Instantly heals a target with an active Rejuvenation or Regrowth effect for an amount equal to the full duration of the periodic effect of one of those spells.", cost = "20% of base mana | 40 yd range | Instant | 15 sec cooldown" },
	{ "When activated, your next Nature spell becomes an instant cast spell.", cost = "Instant | 3 min cooldown" },
	{ "Increases your Spirit by 5%.", "Increases your Spirit by 10%.", "Increases your Spirit by 15%." },
	{ "Reduces threat caused by Tranquility by 50% and its cooldown by 30%.", "Reduces threat caused by Tranquility by 100% and its cooldown by 60%." },
	{ "Increases the critical effect chance of your Regrowth spell by 10%.", "Increases the critical effect chance of your Regrowth spell by 20%.", "Increases the critical effect chance of your Regrowth spell by 30%.", "Increases the critical effect chance of your Regrowth spell by 40%.", "Increases the critical effect chance of your Regrowth spell by 50%." },
	{ "Heals the target and their party for 336 over 7 sec. Party members must be within 43 yards of target. The amount healed is applied quickly at first, and slows down as Wild Growth reaches its full duration.", cost = "550 Mana | 40 yd range | Instant | 6 sec cooldown" },
},
}
